BEGIN;

-- ===== avusturya ===================================================
UPDATE countries SET
  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, Avusturya''ya seyahat etmeden önce vize almak zorundadır.', 'Vizeden Muaf Pasaportlar: Hususi (yeşil), hizmet (gri) ve diplomatik (siyah) pasaport sahipleri, 180 gün içinde 90 günü aşmayan seyahatlerinde vizeden muaftır.', 'Doğru Başvuru Ülkesi: Schengen vizesi başvurusu, seyahatinizde en uzun süre kalmayı planladığınız ülkenin temsilciliğine yapılmalıdır. Birden fazla Schengen ülkesinde eşit süre kalmayı planlıyorsanız, başvurunuzu ilk giriş yapacağınız ülkenin temsilciliğine yapmanız gerekir.', 'Başvuru Merkezi: Avusturya vize başvuruları, ikamet ettiğiniz il için yetkilendirilmiş VFS Global başvuru merkezleri aracılığıyla kabul edilir.', 'Ülkeye Giriş Yetkisi: Schengen vizesi sahibi olmak, ülkeye giriş hakkının kesin olarak tanındığı anlamına gelmez. Nihai değerlendirme, sınır kontrolü sırasında yetkili makamlar tarafından yapılır.']::text[],
  general_info_description = 'Avusturya vize başvurunuza başlamadan önce aşağıdaki temel bilgileri bilmeniz, süreci doğru planlamanıza yardımcı olacaktır.',
  visa_types_description = 'Avusturya''ya yapacağınız seyahatin amacı, başvurmanız gereken vize türünü belirler. Aşağıda Avusturya için en sık başvurulan vize türlerini inceleyebilirsiniz.'

WHERE slug = 'avusturya';

DELETE FROM country_visa_types WHERE country_id = (SELECT id FROM countries WHERE slug = 'avusturya');
DELETE FROM country_process_steps WHERE country_id = (SELECT id FROM countries WHERE slug = 'avusturya');
DELETE FROM country_faqs WHERE country_id = (SELECT id FROM countries WHERE slug = 'avusturya');




-- ===== belcika =====================================================
UPDATE countries SET
  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, Belçika''ya seyahat etmeden önce vize almak zorundadır.', 'Vizeden Muaf Pasaportlar: Hususi (yeşil), hizmet (gri) ve diplomatik (siyah) pasaport sahipleri, 180 gün içinde 90 günü aşmayan seyahatlerinde vizeden muaftır.', 'Doğru Başvuru Ülkesi: Schengen vizesi başvurusu, seyahatinizde en uzun süre kalmayı planladığınız ülkenin temsilciliğine yapılmalıdır. Birden fazla Schengen ülkesinde eşit süre kalmayı planlıyorsanız, başvurunuzu ilk giriş yapacağınız ülkenin temsilciliğine yapmanız gerekir.', 'Başvuru Merkezi: Belçika vize başvuruları, Türkiye''de yetkilendirilmiş VFS Global başvuru merkezleri aracılığıyla kabul edilir. Türkiye''deki C tipi kısa süreli ve D tipi uzun süreli vize başvuruları, Belçika''nın İstanbul Başkonsolosluğu tarafından işleme alınır.', 'Ülkeye Giriş Yetkisi: Schengen vizesi sahibi olmak, ülkeye giriş hakkının kesin olarak tanındığı anlamına gelmez. Nihai değerlendirme, sınır kontrolü sırasında yetkili makamlar tarafından yapılır.']::text[],
