-- ===== bulgaristan =================================================
UPDATE countries SET
  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, Bulgaristan''a seyahat etmeden önce vize almak zorundadır.', 'Vizeden Muaf Pasaportlar: Türkiye Cumhuriyeti diplomatik (siyah) ve hizmet (gri) pasaport sahipleri, kısa süreli seyahatlerinde vizeden muaftır. Hususi (yeşil) pasaport sahipleri için ise vize muafiyeti bulunmamaktadır.', 'Doğru Başvuru Ülkesi: Schengen vizesi başvurusu, seyahatinizde en uzun süre kalmayı planladığınız ülkenin temsilciliğine yapılmalıdır. Birden fazla Schengen ülkesinde eşit süre kalmayı planlıyorsanız, başvurunuzu ilk giriş yapacağınız ülkenin temsilciliğine yapmanız gerekir.', 'Başvuru Merkezi: Bulgaristan vize başvuruları, Türkiye''deki yetkili başvuru merkezleri aracılığıyla kabul edilir. C tipi vize başvuruları Ankara, Bursa, Edirne, Gaziantep ve İstanbul''daki VFS Global merkezlerinden yapılmaktadır. D tipi vize başvurularında ise VFS Global üzerinden önceden randevu alınarak Ankara''daki Bulgaristan Büyükelçiliği''ne şahsen başvurulması gerekmektedir.', 'Ülkeye Giriş Yetkisi: Schengen vizesi sahibi olmak, ülkeye giriş hakkının kesin olarak tanındığı anlamına gelmez. Nihai değerlendirme, sınır kontrolü sırasında yetkili makamlar tarafından yapılır.']::text[],
  general_info_description = 'Bulgaristan vize başvurunuza başlamadan önce aşağıdaki temel bilgileri bilmeniz, süreci doğru planlamanıza yardımcı olacaktır.',
  visa_types_description = 'Bulgaristan''a yapacağınız seyahatin amacı, başvurmanız gereken vize türünü belirler. Aşağıda Bulgaristan için en sık başvurulan vize türlerini inceleyebilirsiniz.'

WHERE slug = 'bulgaristan';

DELETE FROM country_visa_types WHERE country_id = (SELECT id FROM countries WHERE slug = 'bulgaristan');
DELETE FROM country_process_steps WHERE country_id = (SELECT id FROM countries WHERE slug = 'bulgaristan');
DELETE FROM country_faqs WHERE country_id = (SELECT id FROM countries WHERE slug = 'bulgaristan');




