UPDATE countries SET
  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, İsviçre''ye seyahat etmeden önce vize almak zorundadır.', 'Vizeden Muaf Pasaportlar: Hususi (yeşil), hizmet (gri) ve diplomatik (siyah) pasaport sahipleri, 180 gün içinde 90 günü aşmayan seyahatlerinde vizeden muaftır.', 'Doğru Başvuru Ülkesi: Schengen vizesi başvurusu, seyahatinizde en uzun süre kalmayı planladığınız ülkenin temsilciliğine yapılmalıdır. Birden fazla Schengen ülkesinde eşit süre kalmayı planlıyorsanız, başvurunuzu ilk giriş yapacağınız ülkenin temsilciliğine yapmanız gerekir.', 'Başvuru Merkezi: İsviçre vize başvuruları, Türkiye''de İsviçre''nin Ankara ve İstanbul''daki temsilcilikleri tarafından yetkilendirilen VFS Global başvuru merkezleri aracılığıyla kabul edilir. Türkiye''de İstanbul ve Ankara''da VFS Global başvuru merkezleri bulunmaktadır.', 'Ülkeye Giriş Yetkisi: Schengen vizesi sahibi olmak, ülkeye giriş hakkının kesin olarak tanındığı anlamına gelmez. Nihai değerlendirme, sınır kontrolü sırasında yetkili makamlar tarafından yapılır.']::text[],
  general_info_description = 'İsviçre vize başvurunuza başlamadan önce aşağıdaki temel bilgileri bilmeniz, süreci doğru planlamanıza yardımcı olacaktır.',
  visa_types_description = 'İsviçre''ye yapacağınız seyahatin amacı, başvurmanız gereken vize türünü belirler. Aşağıda İsviçre için en sık başvurulan vize türlerini inceleyebilirsiniz.'

WHERE slug = 'isvicre';

DELETE FROM country_visa_types WHERE country_id = (SELECT id FROM countries WHERE slug = 'isvicre');
DELETE FROM country_process_steps WHERE country_id = (SELECT id FROM countries WHERE slug = 'isvicre');
DELETE FROM country_faqs WHERE country_id = (SELECT id FROM countries WHERE slug = 'isvicre');




-- ===== italya ======================================================
UPDATE countries SET
  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, İtalya''ya seyahat etmeden önce vize almak zorundadır.', 'Vizeden Muaf Pasaportlar: Hususi (yeşil), hizmet (gri) ve diplomatik (siyah) pasaport sahipleri, 180 gün içinde 90 günü aşmayan seyahatlerinde vizeden muaftır.', 'Doğru Başvuru Ülkesi: Schengen vizesi başvurusu, seyahatinizde en uzun süre kalmayı planladığınız ülkenin temsilciliğine yapılmalıdır. Birden fazla Schengen ülkesinde eşit süre kalmayı planlıyorsanız, başvurunuzu ilk giriş yapacağınız ülkenin temsilciliğine yapmanız gerekir.', 'Başvuru Merkezi: İtalya vize başvuruları, başvuru sahibinin ikamet ettiği konsolosluk yetki alanına göre yetkilendirilmiş iDATA başvuru merkezleri aracılığıyla kabul edilir. İtalya''nın İstanbul Başkonsolosluğu, kendi konsolosluk yetki alanında yasal olarak ikamet eden başvuru sahiplerinin iDATA üzerinden randevu almasını öngörmektedir.', 'Ülkeye Giriş Yetkisi: Schengen vizesi sahibi olmak, ülkeye giriş hakkının kesin olarak tanındığı anlamına gelmez. Nihai değerlendirme, sınır kontrolü sırasında yetkili makamlar tarafından yapılır.']::text[],
  general_info_description = 'İtalya vize başvurunuza başlamadan önce aşağıdaki temel bilgileri bilmeniz, süreci doğru planlamanıza yardımcı olacaktır.',
  visa_types_description = 'İtalya''ya yapacağınız seyahatin amacı, başvurmanız gereken vize türünü belirler. Aşağıda İtalya için en sık başvurulan vize türlerini inceleyebilirsiniz.'

WHERE slug = 'italya';

