  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, Polonya''ya kısa süreli seyahatlerinde vize almak zorundadır.', 'Vizeden Muaf Pasaportlar: Türkiye Cumhuriyeti hususi (yeşil), hizmet (gri) ve diplomatik (siyah) pasaport sahipleri, 180 gün içinde 90 günü aşmayan kısa süreli seyahatlerinde vizeden muaftır.', 'Doğru Başvuru Ülkesi: Schengen vizesi başvurusu, seyahatinizde en uzun süre kalmayı planladığınız ülkenin temsilciliğine yapılmalıdır. Birden fazla Schengen ülkesinde eşit süre kalmayı planlıyorsanız, başvurunuzu ilk giriş yapacağınız ülkenin temsilciliğine yapmanız gerekir. Polonya''ya başvurabilmeniz için Polonya''nın seyahatinizin tek veya ana destinasyonu olması gerekir.', 'Başvuru Merkezi: Polonya''nın Türkiye''deki kısa süreli Schengen vize başvuruları VFS Global Vize Başvuru Merkezleri aracılığıyla kabul edilmektedir. Başvurular Türkiye''deki yetkili merkezlerden randevu alınarak şahsen yapılır.', 'Ülkeye Giriş Yetkisi: Schengen vizesi sahibi olmak, Polonya''ya veya Schengen bölgesine giriş hakkının kesin olarak tanındığı anlamına gelmez. Nihai değerlendirme, sınır kontrolü sırasında yetkili makamlar tarafından yapılır.']::text[],
  general_info_description = 'Polonya vize başvurunuza başlamadan önce aşağıdaki temel bilgileri bilmeniz, süreci doğru planlamanıza yardımcı olacaktır.',
  visa_types_description = 'Polonya''ya yapacağınız seyahatin amacı ve kalış süresi, başvurmanız gereken vize türünü belirler. Aşağıda Polonya için en sık başvurulan vize türlerini inceleyebilirsiniz.'

WHERE slug = 'polonya';

DELETE FROM country_visa_types WHERE country_id = (SELECT id FROM countries WHERE slug = 'polonya');
DELETE FROM country_process_steps WHERE country_id = (SELECT id FROM countries WHERE slug = 'polonya');
DELETE FROM country_faqs WHERE country_id = (SELECT id FROM countries WHERE slug = 'polonya');




