-- ===== romanya =====================================================
UPDATE countries SET
  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, Romanya''ya kısa süreli seyahatlerinde vize almak zorundadır. Romanya, 31 Mart 2024 tarihinden itibaren Schengen bölgesinin tam üyesidir.', 'Vizeden Muaf Pasaportlar: Türkiye Cumhuriyeti hususi (yeşil), hizmet (gri) ve diplomatik (siyah) pasaport sahiplerinin kısa süreli Romanya seyahatlerinde vize durumu, pasaport türüne ve seyahatin koşullarına göre değerlendirilmelidir.', 'Doğru Başvuru Ülkesi: Schengen vizesi başvurusu, seyahatinizde en uzun süre kalmayı planladığınız ülkenin temsilciliğine yapılmalıdır. Birden fazla Schengen ülkesinde eşit süre kalmayı planlıyorsanız, başvurunuzu ilk giriş yapacağınız ülkenin temsilciliğine yapmanız gerekir.', 'Başvuru Merkezi: Romanya vize başvuruları, Romanya Dışişleri Bakanlığı''nın eViza portalı üzerinden online olarak başlatılır. Başvuru formu ve gerekli belgeler elektronik ortamda sisteme yüklenir ve başvuru, yetkili Romanya diplomatik misyonu veya konsolosluk biriminde tamamlanır.', 'Ülkeye Giriş Yetkisi: Schengen vizesi sahibi olmak, Romanya''ya veya Schengen bölgesine giriş hakkının kesin olarak tanındığı anlamına gelmez. Sınır kontrolünde seyahatin amacı, kalış süresi ve diğer giriş koşullarının karşılandığının gösterilmesi gerekebilir.']::text[],
  general_info_description = 'Romanya vize başvurunuza başlamadan önce aşağıdaki temel bilgileri bilmeniz, süreci doğru planlamanıza yardımcı olacaktır.',
  visa_types_description = 'Romanya''ya yapacağınız seyahatin amacı ve kalış süresi, başvurmanız gereken vize türünü belirler. Aşağıda Romanya için en sık başvurulan vize türlerini inceleyebilirsiniz.'

WHERE slug = 'romanya';

DELETE FROM country_visa_types WHERE country_id = (SELECT id FROM countries WHERE slug = 'romanya');
DELETE FROM country_process_steps WHERE country_id = (SELECT id FROM countries WHERE slug = 'romanya');
DELETE FROM country_faqs WHERE country_id = (SELECT id FROM countries WHERE slug = 'romanya');




