  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, İrlanda''ya seyahat etmeden önce vize almak zorundadır.', 'Vizeden Muaf Pasaportlar: Hususi (yeşil), hizmet (gri) ve umuma mahsus (bordo) pasaport sahipleri de dâhil olmak üzere T.C. pasaport sahipleri İrlanda seyahatlerinde vizeye tabidir. (İrlanda, Schengen vize muafiyet kurallarına dâhil değildir).', 'Doğru Başvuru Sistemi: İrlanda vize başvurusu, doğrudan İrlanda Göçmenlik Makamı''nın resmi çevrim içi sistemi AVATS üzerinden başlatılmalıdır.', 'Başvuru Merkezi: İrlanda vize başvuruları, AVATS formu tamamlandıktan sonra yetkilendirilmiş VFS Global başvuru merkezleri aracılığıyla kabul edilir.', 'Ülkeye Giriş Yetkisi: İrlanda vizesi sahibi olmak, ülkeye giriş hakkının kesin olarak tanındığı anlamına gelmez. Nihai değerlendirme, sınır kontrolü sırasında İrlanda Sınır Kontrol yetkilileri tarafından yapılır.']::text[],
  general_info_description = 'İrlanda vize başvurunuza başlamadan önce aşağıdaki temel bilgileri bilmeniz, süreci doğru planlamanıza yardımcı olacaktır.',
  visa_types_description = 'Doğru vize türüne başvurmak, başvuru sürecinin en önemli adımlarından biridir. İrlanda''ya yapacağınız seyahatin amacı, başvurmanız gereken vize türünü belirler.'

WHERE slug = 'irlanda';

DELETE FROM country_visa_types WHERE country_id = (SELECT id FROM countries WHERE slug = 'irlanda');
DELETE FROM country_process_steps WHERE country_id = (SELECT id FROM countries WHERE slug = 'irlanda');
DELETE FROM country_faqs WHERE country_id = (SELECT id FROM countries WHERE slug = 'irlanda');




-- ===== kanada ======================================================
UPDATE countries SET
  general_info = ARRAY['Vize Zorunluluğu: Türkiye Cumhuriyeti umuma mahsus (bordo) pasaport sahipleri, Kanada''ya seyahat etmeden önce vize almak zorundadır.', 'Vizeden Muaf Pasaportlar: Hususi (yeşil), hizmet (gri) ve diplomatik (siyah) pasaport sahipleri de dâhil olmak üzere tüm T.C. pasaport türleri Kanada seyahatlerinde vizeye tabidir.', 'Doğru Başvuru Sistemi: Kanada vize başvurusu, Kanada Hükümeti''nin resmi platformu olan IRCC Portal üzerinden dijital olarak başlatılır ve tüm belgeler sisteme online olarak yüklenir.', 'Başvuru Merkezi: Başvuru internetten tamamlandıktan sonra biyometrik işlemler (parmak izi ve fotoğraf) yetkilendirilmiş VFS Global Kanada Vize Başvuru Merkezleri aracılığıyla yapılır.', 'Ülkeye Giriş Yetkisi: Kanada vizesi sahibi olmak, ülkeye giriş hakkının kesin olarak tanındığı anlamına gelmez. Nihai değerlendirme, havalimanındaki sınır kontrolü sırasında Kanada Sınır Hizmetleri Ajansı (CBSA) memurları tarafından yapılır.']::text[],
  general_info_description = 'Kanada vize başvurunuza başlamadan önce aşağıdaki temel bilgileri bilmeniz, süreci doğru planlamanıza yardımcı olacaktır.',
  visa_types_description = 'Doğru vize türüne başvurmak, başvuru sürecinin en önemli adımlarından biridir. Kanada''ya yapacağınız seyahatin amacı, başvurmanız gereken vize türünü belirler.'

WHERE slug = 'kanada';

DELETE FROM country_visa_types WHERE country_id = (SELECT id FROM countries WHERE slug = 'kanada');
DELETE FROM country_process_steps WHERE country_id = (SELECT id FROM countries WHERE slug = 'kanada');
DELETE FROM country_faqs WHERE country_id = (SELECT id FROM countries WHERE slug = 'kanada');




-- ===== schengen ====================================================
UPDATE countries SET
  general_info = ARRAY['Schengen Bölgesi: Schengen Bölgesi, üye ülkeler arasındaki iç sınır kontrollerinin kaldırıldığı ve ortak vize kurallarının uygulandığı 29 Avrupa ülkesinden oluşur.', 'Vize Zorunluluğu: Umuma Mahsus (Bordo) pasaport sahiplerinin, Schengen Bölgesi''ne yapacakları 90 güne kadar olan kısa süreli seyahatler için Schengen vizesi almaları gerekir.', 'Vizeden Muaf Pasaportlar: Hususi (Yeşil), Hizmet (Gri) ve Diplomatik (Siyah) pasaport sahipleri, 180 günlük dönem içinde 90 günü aşmayan kısa süreli seyahatlerinde Schengen vizesinden muaftır.', '90/180 Kuralı: Kısa süreli Schengen seyahatlerinde, herhangi bir 180 günlük dönem içinde Schengen Bölgesi''nde toplam 90 günden fazla kalamazsınız. Bu süre, Schengen Bölgesi''ne yaptığınız tüm giriş ve çıkışlar birlikte değerlendirilerek hesaplanır.', 'Başvuru Ülkesi: Schengen vize başvurunuzu, seyahatinizin ana destinasyonu olan ülkenin yetkili makamlarına yapmanız gerekir. Birden fazla Schengen ülkesini ziyaret edecekseniz, genel olarak en uzun süre kalacağınız ülke esas alınır. Birden fazla ülkede eşit süre kalmanız durumunda ise ilk giriş yapacağınız ülkeye başvurmanız gerekir.']::text[],
  general_info_description = 'Schengen vizesi başvurularında ortak Schengen kuralları uygulanır. Başvurunuza başlamadan önce aşağıdaki temel bilgileri gözden geçirmenizi öneririz.',
  visa_types_description = 'Schengen vizeleri, 90 güne kadar olan kısa süreli seyahatler için düzenlenen C Tipi vizelerdir. Seyahat amacınıza göre başvurmanız gereken kategori değişir. 90 günü aşan eğitim, çalışma veya yerleşim gibi amaçlarda ise Schengen vizesi değil, seyahat edeceğiniz ülkenin ulusal D Tipi vizesine başvurmanız gerekir.',
  general_info_title = 'Schengen Vizesinin Temel Kuralları',
  visa_types_title = 'Hangi Schengen Vize Türüne Başvurmalısınız?',
  summary = 'Turistik, ticari ve aile ziyareti gibi 90 güne kadar olan kısa süreli seyahatler için tek vizeyle Schengen Bölgesi''ndeki 29 ülkeye seyahat edebilirsiniz.'
WHERE slug = 'schengen';

DELETE FROM country_visa_types WHERE country_id = (SELECT id FROM countries WHERE slug = 'schengen');
DELETE FROM country_process_steps WHERE country_id = (SELECT id FROM countries WHERE slug = 'schengen');
DELETE FROM country_faqs WHERE country_id = (SELECT id FROM countries WHERE slug = 'schengen');




COMMIT;