INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Avusturya''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Aile Ziyareti Vizesi', 'Avusturya''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Aile Birleşimi Vizesi', 'Avusturya''da yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Öğrenci Vizesi', 'Avusturya''da üniversite eğitimi veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Çalışma Vizesi', 'Avusturya''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Transit Vizesi', 'Avusturya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Havaalanı Transit (A Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Avusturya''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Vize Türünün Belirlenmesi', 'Avusturya vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Form ve Evrak Hazırlığı', 'Avusturya vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Konsolosluk veya yetkili makamlar gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun konsolosluğa ulaşmasının ardından genellikle 15 takvim günü içerisinde sonuçlandırılır. Ancak ek belge talep edilmesi, yoğun başvuru dönemleri veya başvurunun detaylı incelemeye alınması durumunda bu süre uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vize ücreti ne kadar?', 'Avusturya vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Avusturya vize başvurusunda seyahat süresince yeterli maddi imkâna sahip olduğunuzu gösteren belgelerin sunulması gerekir. Başvurunuz değerlendirilirken yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak son 59 ay içinde herhangi bir Schengen ülkesi için biyometrik veri verdiyseniz, bu veriler geçerliliğini koruyorsa yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin geçerlilik süresi dolmuşsa, başvuru merkezine şahsen giderek parmak izi vermeniz gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Avusturya tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya ana giriş yapacağınız ülkenin Avusturya olması gerekir. Ayrıca pasaport kontrolünde seyahat amacınızı ve planınızı kanıtlayan belgeleri (otel rezervasyonu, dönüş bileti vb.) yanınızda taşımanız önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya Schengen vizesi ne kadar süreyle verilir?', 'Avusturya tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, olumlu Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vize başvuruları en çok hangi nedenlerle reddedilir?', 'Avusturya vize başvurularının reddedilmesindeki en yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'Avusturya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Avusturya vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'avusturya'), 'İlk girişimi Avusturya''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Avusturya''dan aldıysanız, seyahatinizin en uzun süren kısmını Avusturya''da geçirmeli veya seyahatinizin ana hedefi Avusturya olmalıdır.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Belçika''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Aile Ziyareti Vizesi', 'Belçika''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Aile Birleşimi Vizesi', 'Belçika''da yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Öğrenci Vizesi', 'Belçika''da üniversite eğitimi, yükseköğrenim veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Çalışma Vizesi', 'Belçika''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Transit Vizesi', 'Belçika üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Havaalanı Transit (A Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Belçika''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Vize Türünün Belirlenmesi', 'Belçika vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Form ve Evrak Hazırlığı', 'Belçika vize başvuru formu Visa on Web (VOW) portalı üzerinden doldurulur. Form tamamlandıktan sonra başvuru sahibi VFS Global''in randevu sistemine yönlendirilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde vize başvuru formu ve gerekli belgeler teslim edilir. Gerekli olması hâlinde parmak izi ve fotoğraf işlemleri gerçekleştirilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra işlem için İstanbul''daki Belçika Başkonsolosluğu''na gönderilir. Başvuru süreci boyunca dosyanızın durumunu çevrimiçi olarak takip edebilirsiniz. Yetkili Belçika makamları gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir veya ek ücret karşılığında kurye ile adresinize gönderilebilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Başvuruların seyahatten en geç 15 takvim günü önce yapılması gerekir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları normal şartlarda başvurunun sunulmasının ardından genellikle 15 gün içerisinde sonuçlandırılır. Başvurunun daha ayrıntılı incelenmesi veya Belçika Göçmenlik Ofisi''nin değerlendirmesine gönderilmesi gereken durumlarda işlem süresi yaklaşık 45 güne kadar uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vize ücreti ne kadar?', 'Belçika vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Belçika''da kısa süreli seyahatlerde yeterli maddi imkâna sahip olduğunuzu göstermeniz gerekir. Belçika''nın resmî referans tutarı, otelde konaklayan kişiler için günlük 95 Euro, arkadaş veya aile yanında konaklayan kişiler için ise günlük 45 Euro''dur. Finansal yeterlilik değerlendirilirken gelir durumunuz, banka hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte dikkate alınabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik işlemler gerçekleştirilir. Ancak daha önce alınmış biyometrik verilerin geçerli olduğu durumlarda yeniden parmak izi alınması gerekmeyebilir. Belçika''nın Türkiye''deki resmî başvuru prosedürüne göre randevu sırasında gerekli olması hâlinde parmak izi ve fotoğraf alınır.', 5),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Belçika tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya seyahatinizin ana hedefini oluşturan ülkenin Belçika olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika Schengen vizesi ne kadar süreyle verilir?', 'Belçika tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat amacı, seyahat geçmişi ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. Vizenin geçerlilik süresi ve giriş hakkı, başvuruyu değerlendiren yetkili makamların kararı doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vize başvuruları en çok hangi nedenlerle reddedilir?', 'Belçika vize başvurularının reddedilmesinde; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin seyahat sonunda Schengen bölgesinden ayrılacağına ilişkin yeterli kanaat oluşmaması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'Belçika vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Belçika vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'belcika'), 'İlk girişimi Belçika''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Belçika''dan aldıysanız seyahatinizin en uzun süren kısmını Belçika''da geçirmeli veya seyahatinizin ana hedefi Belçika olmalıdır.', 10);
