  ((SELECT id FROM countries WHERE slug = 'cekya'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Çek Cumhuriyeti''nin yetkili makamları gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'cekya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
