  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Başvuruların planlanan seyahatten en geç 15 gün önce yapılması gerekir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız önemlidir.', 0),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun yetkili makama ulaşmasının ardından genellikle 15 takvim günü içerisinde sonuçlandırılır. Ancak ek belge talep edilmesi veya başvurunun daha ayrıntılı incelemeye alınması durumunda bu süre 45 güne kadar uzayabilir. Danimarka''nın Türkiye''deki resmî makamları ayrıca güncel dönemde olağan dışı başvuru yoğunluğu nedeniyle işlemlerin normalden daha uzun sürebildiğini belirtmektedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vize ücreti ne kadar?', 'Danimarka vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Danimarka vize başvurusunda seyahat süresince yeterli maddi imkâna sahip olduğunuzu gösteren belgelerin sunulması gerekir. Başvurunuz değerlendirilirken yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak son 59 ay içinde herhangi bir Schengen ülkesi için biyometrik veri verdiyseniz, bu veriler geçerliliğini koruyorsa yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin geçerlilik süresi dolmuşsa, başvuru merkezine şahsen giderek parmak izi vermeniz gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Danimarka tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurunuzun Danimarka''ya yapılabilmesi için Danimarka''nın seyahatinizin ana destinasyonu olması gerekir. Danimarka makamları, Danimarka''yı ana destinasyonunuz olarak göstermeden alınan bir Danimarka Schengen vizesiyle başka bir Schengen ülkesine seyahat edilmesi durumunda girişte sorun yaşanabileceği ve vizenin iptal edilebileceği konusunda uyarıda bulunmaktadır.', 6),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka Schengen vizesi ne kadar süreyle verilir?', 'Danimarka tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, olumlu Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vize başvuruları en çok hangi nedenlerle reddedilir?', 'Danimarka vize başvurularının reddedilmesindeki en yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'Danimarka vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Danimarka vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'danimarka'), 'İlk girişimi Danimarka''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Danimarka''dan aldıysanız, Danimarka seyahatinizin ana destinasyonu olmalıdır. Seyahatinizde başka bir Schengen ülkesinde daha uzun süre kalmayı planlıyorsanız, vize başvurunuzu o ülkeye yapmanız gerekir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Estonya''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Aile Ziyareti Vizesi', 'Estonya''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Aile Birleşimi Vizesi', 'Estonya''da yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Öğrenci Vizesi', 'Estonya''da eğitim veya araştırma amacıyla uzun süreli bulunacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Çalışma Vizesi', 'Estonya''da çalışmak veya uzun süreli mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Transit Vizesi', 'Estonya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Havaalanı Transit (A Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Estonya''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Vize Türünün Belirlenmesi', 'Estonya vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Form ve Evrak Hazırlığı', 'Estonya vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Estonya''nın yetkili makamları gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları normal şartlarda başvurunun yetkili makamlara ulaşmasının ardından genellikle 15 takvim günü içerisinde sonuçlandırılır. Ancak ek belge talep edilmesi veya başvurunun daha ayrıntılı incelenmesi gereken durumlarda bu süre uzayabilir. Seyahat planınızı riske atmamak için başvurunuzu son güne bırakmamanız önerilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vize ücreti ne kadar?', 'Estonya vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak güncel tarifeye göre değişiklik gösterebilir. Ayrıca yetkili başvuru merkezi tarafından hizmet bedeli alınabilir. Başvuru öncesinde güncel ücretlerin kontrol edilmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Estonya vize başvurusunda seyahat süresince ulaşım, konaklama ve diğer masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Finansal durumunuz değerlendirilirken geliriniz, banka hesap hareketleriniz ve sunduğunuz diğer belgeler birlikte dikkate alınabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen vize başvurularında pasaportunuzun planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması, en az 2 boş sayfa içermesi ve son 10 yıl içinde düzenlenmiş olması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır. Daha önceki bir Schengen başvurusunda alınan parmak izlerinin geçerli olduğu durumlarda yeniden parmak izi alınması gerekmeyebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Estonya tarafından verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken seyahatinizin ana destinasyonunun Estonya olması veya Schengen kurallarına göre Estonya''nın başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya Schengen vizesi ne kadar süreyle verilir?', 'Estonya tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat amacı, seyahat geçmişi ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. Vizenin geçerlilik süresi ve giriş sayısı yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vize başvuruları en çok hangi nedenlerle reddedilir?', 'Estonya vize başvurularının reddedilmesinde; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'Estonya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Estonya vize başvurunuzun reddedilmesi, yeni bir başvuru yapılmasına engel değildir. Ancak yeni bir başvuru öncesinde ret gerekçesinin dikkatle değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'estonya'), 'İlk girişimi Estonya''dan yapmak zorunda mıyım?', 'Schengen vize başvurularında başvuru yapılacak ülke, seyahatin ana destinasyonuna göre belirlenir. Estonya''dan alınan bir Schengen vizesiyle başka bir Schengen ülkesinden giriş yapılması tek başına vizeyi geçersiz hâle getirmez; ancak seyahat planınızın vizenin verildiği ülkeyi ana destinasyon olarak göstermesi gerekir.', 10);
