  ((SELECT id FROM countries WHERE slug = 'finlandiya'), 'Finlandiya vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen vize başvurularında pasaportunuzun planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması, en az 2 boş sayfa içermesi ve son 10 yıl içinde düzenlenmiş olması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'finlandiya'), 'Finlandiya vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır. Daha önceki bir Schengen vize başvurusunda alınan parmak izlerinin geçerli olduğu durumlarda yeniden parmak izi alınması gerekmeyebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'finlandiya'), 'Finlandiya vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Finlandiya tarafından verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken seyahatinizin ana destinasyonunun Finlandiya olması veya Schengen kurallarına göre Finlandiya''nın başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'finlandiya'), 'Finlandiya Schengen vizesi ne kadar süreyle verilir?', 'Finlandiya tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat amacı, seyahat geçmişi ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. Vizenin geçerlilik süresi ve giriş sayısı yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'finlandiya'), 'Finlandiya vize başvuruları en çok hangi nedenlerle reddedilir?', 'Finlandiya vize başvurularının reddedilmesinde; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'finlandiya'), 'Finlandiya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Finlandiya vize başvurunuzun reddedilmesi, yeni bir başvuru yapılmasına engel değildir. Ancak yeni bir başvuru öncesinde ret gerekçesinin dikkatle değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'finlandiya'), 'İlk girişimi Finlandiya''dan yapmak zorunda mıyım?', 'Schengen vize başvurularında başvuru yapılacak ülke, seyahatin ana destinasyonuna göre belirlenir. Finlandiya''dan alınan bir Schengen vizesiyle başka bir Schengen ülkesinden giriş yapılması tek başına vizeyi geçersiz hâle getirmez; ancak seyahat planınızın vizenin verildiği ülkeyi ana destinasyon olarak göstermesi gerekir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Fransa''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Aile Ziyareti Vizesi', 'Fransa''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Aile Birleşimi Vizesi', 'Fransa''da yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Öğrenci Vizesi', 'Fransa''da üniversite eğitimi veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Çalışma Vizesi', 'Fransa''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Transit Vizesi', 'Fransa üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği havaalanı transit vizesidir. Türkiye Cumhuriyeti vatandaşları, Fransa havalimanlarının uluslararası transit alanından başka bir ülkeye geçişlerinde belirli koşullarda havaalanı transit vizesine tabi olabilir.', 6),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Fransa''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Vize Türünün Belirlenmesi', 'Fransa vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Form ve Evrak Hazırlığı', 'Fransa vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde yetkili VFS Global başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Fransa''nın Türkiye''deki vize başvuruları Ankara''daki Fransa Büyükelçiliği ve İstanbul''daki Fransa Başkonsolosluğu tarafından incelenir ve vize kararları bu yetkili makamlar tarafından verilir. Gerekli görülen durumlarda ek belge veya bilgi talep edilebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir. Fransa''nın Türkiye''deki resmi bilgilendirmesinde de randevu sürelerinin dönemsel yoğunluğa göre değişebileceği belirtilmektedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vizesi kaç günde sonuçlanır?', 'Fransa Schengen vize başvurularının sonuçlanma süresi, başvurunun niteliğine, dönemsel yoğunluğa ve gerekli görülmesi hâlinde ek belge veya inceleme talep edilmesine göre değişebilir. Bu nedenle başvurunuz için kesin bir sonuçlanma süresi garanti edilemez. Seyahat planınızı riske atmamak için başvurunuzu son güne bırakmamanız önerilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vize ücreti ne kadar?', 'Fransa vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak güncel konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde ek başvuru hizmetlerinden oluşabilir. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Fransa vize başvurusunda seyahat süreniz boyunca ulaşım, konaklama ve diğer masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Bununla birlikte yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin yeniden alınması gerekiyorsa, başvuru merkezine şahsen giderek biyometrik işlemlerinizi tamamlamanız gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Fransa tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya ana hedefiniz olan ülkenin Fransa olması gerekir. Ayrıca seyahat planınızın vize başvurusu sırasında sunduğunuz bilgilerle uyumlu olması önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa Schengen vizesi ne kadar süreyle verilir?', 'Fransa tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, uygun Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vize başvuruları en çok hangi nedenlerle reddedilir?', 'Fransa vize başvurularının reddedilmesindeki yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'Fransa vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Fransa vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'fransa'), 'İlk girişimi Fransa''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Fransa''dan aldıysanız, seyahatinizin en uzun süren kısmını Fransa''da geçirmeli veya seyahatinizin ana hedefi Fransa olmalıdır. Vize başvurusunda sunduğunuz seyahat planının gerçek seyahatinizle uyumlu olması önemlidir.', 10);
