  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan Aile Ziyareti Vizesi', 'Hırvatistan''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan Aile Birleşimi Vizesi', 'Hırvatistan''da yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan Öğrenci Vizesi', 'Hırvatistan''da üniversite eğitimi veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan Çalışma Vizesi', 'Hırvatistan''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan Transit Vizesi', 'Hırvatistan üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Schengen (A Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Hırvatistan''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Vize Türünün Belirlenmesi', 'Hırvatistan vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Form ve Evrak Hazırlığı', 'Hırvatistan vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Yetkili Hırvatistan makamları gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun konsolosluğa ulaşmasının ardından genellikle 15 takvim günü içerisinde sonuçlandırılır. Ancak ek belge talep edilmesi, yoğun başvuru dönemleri veya başvurunun detaylı incelemeye alınması durumunda bu süre 45 takvim gününe kadar uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vize ücreti ne kadar?', 'Hırvatistan vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Hırvatistan vize başvurusunda seyahat süresince yeterli maddi imkâna sahip olduğunuzu gösteren belgelerin sunulması gerekir. Başvurunuz değerlendirilirken yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak son 59 ay içinde herhangi bir Schengen ülkesi için biyometrik veri verdiyseniz, bu veriler geçerliliğini koruyorsa yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin geçerlilik süresi dolmuşsa, başvuru merkezine şahsen giderek parmak izi vermeniz gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Hırvatistan tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya ana giriş yapacağınız ülkenin Hırvatistan olması gerekir. Ayrıca pasaport kontrolünde seyahat amacınızı ve planınızı kanıtlayan belgeleri (otel rezervasyonu, dönüş bileti vb.) yanınızda taşımanız önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan Schengen vizesi ne kadar süreyle verilir?', 'Hırvatistan tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, olumlu Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vize başvuruları en çok hangi nedenlerle reddedilir?', 'Hırvatistan vize başvurularının reddedilmesindeki en yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'Hırvatistan vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Hırvatistan vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'hirvatistan'), 'İlk girişimi Hırvatistan''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Hırvatistan''dan aldıysanız, seyahatinizin en uzun süren kısmını Hırvatistan''da geçirmeli veya seyahatinizin ana hedefi Hırvatistan olmalıdır.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Hollanda''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Aile Ziyareti Vizesi', 'Hollanda''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Aile Birleşimi Vizesi', 'Hollanda''da yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan uzun süreli vize ve oturum prosedürüdür.', 3),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Öğrenci Vizesi', 'Hollanda''da üniversite eğitimi veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği uzun süreli vize ve oturum prosedürüdür.', 4),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Çalışma Vizesi', 'Hollanda''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği uzun süreli vize ve oturum prosedürüdür.', 5),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Transit Vizesi', 'Hollanda üzerinden başka bir ülkeye havaalanı transit geçişi yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Havaalanı Transit Vizesidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Hollanda''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Vize Türünün Belirlenmesi', 'Hollanda vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Form ve Evrak Hazırlığı', 'Hollanda vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Hollanda Dışişleri Bakanlığı gerekli gördüğü durumlarda ek belge veya görüşme talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Hollanda için başvuruların seyahat tarihinden en geç 45 gün önce yapılması gerekir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vizesi kaç günde sonuçlanır?', 'Hollanda Schengen vize başvuruları, güncel olarak ortalama 25 takvim günü içerisinde sonuçlandırılmaktadır. Ancak ek belge talep edilmesi, yoğun başvuru dönemleri veya başvurunun daha ayrıntılı incelemeye alınması durumunda bu süre 45 takvim gününe kadar uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vize ücreti ne kadar?', 'Hollanda vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Hollanda makamları tarafından belirlenmiş tek bir resmi minimum banka bakiyesi bulunmamaktadır. Başvurunuz değerlendirilirken hesabınızda, seyahat süreniz boyunca ulaşım, konaklama ve diğer masraflarınızı karşılayabilecek yeterli finansal kaynağın bulunması beklenir. Bununla birlikte yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında 12 yaş ve üzerindeki başvuru sahiplerinden biyometrik veri (parmak izi) alınır. Ancak son 59 ay içinde herhangi bir Schengen ülkesi için biyometrik veri verdiyseniz, bu veriler geçerliliğini koruyorsa yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin geçerlilik süresi dolmuşsa, başvuru merkezine şahsen giderek parmak izi vermeniz gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Hollanda tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya ana giriş yapacağınız ülkenin Hollanda olması gerekir. Ayrıca pasaport kontrolünde seyahat amacınızı ve planınızı kanıtlayan belgeleri (otel rezervasyonu, dönüş bileti vb.) yanınızda taşımanız önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda Schengen vizesi ne kadar süreyle verilir?', 'Hollanda tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, olumlu Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen konsolosluğun değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vize başvuruları en çok hangi nedenlerle reddedilir?', 'Hollanda vize başvurularının reddedilmesindeki en yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'Hollanda vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Hollanda vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'hollanda'), 'İlk girişimi Hollanda''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Hollanda''dan aldıysanız, seyahatinizin en uzun süren kısmını Hollanda''da geçirmeli veya seyahatinizin ana hedefi Hollanda olmalıdır.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla İspanya''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Aile Ziyareti Vizesi', 'İspanya''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Aile Birleşimi Vizesi', 'İspanya''da yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Öğrenci Vizesi', 'İspanya''da üniversite eğitimi veya 90 günden uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir. 90 güne kadar olan eğitimlerde ise koşullara göre Schengen vizesi uygulanabilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Çalışma Vizesi', 'İspanya''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Transit Vizesi', 'İspanya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Havaalanı Transit (A Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'İspanya''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir. Ticari, kültürel ve benzeri kısa süreli faaliyetler Schengen vizesi kapsamında değerlendirilebilir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'Vize Türünün Belirlenmesi', 'İspanya vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'Form ve Evrak Hazırlığı', 'İspanya vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde yetkili BLS International başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri gerçekleştirilir. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir. İspanya''nın resmi başvuru prosedüründe başvuru sırasında yüz görüntüsü ve parmak izi alınmaktadır.', 2),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Konsolosluk veya yetkili makamlar gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi veya konsolosluğun belirlediği yöntem aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. İspanya''nın resmi bilgilendirmesine göre başvuruların seyahat tarihinden en az 15 gün önce yapılması gerekir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun sunulmasının ardından 15 takvim günü içerisinde sonuçlandırılır. Ancak bazı başvurularda ek inceleme veya yetkili makamlarla istişare gerekmesi halinde değerlendirme süresi uzayabilir. Seyahat planınızı riske atmamak için başvurunuzu son güne bırakmamanız önerilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vize ücreti ne kadar?', 'İspanya vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak güncel konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'İspanya vize başvurusunda seyahat süreniz boyunca ulaşım, konaklama ve diğer masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Başvurunun değerlendirilmesinde finansal durumunuzu gösteren belgeler ile seyahat amacınızı ve koşullarınızı destekleyen diğer belgeler birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur.', 4),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri alınması gerekmektedir. Başvuru sırasında yüz görüntüsü ve parmak izi alınır. Daha önce alınmış biyometrik verilerin geçerli olduğu durumlarda yeniden parmak izi alınması gerekmeyebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'İspanya tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak seyahatiniz birden fazla ülkeyi kapsıyorsa, başvurunun İspanya''nın seyahatinizdeki tek veya ana destinasyon olması esasına göre yapılmış olması gerekir. Ayrıca Schengen vizesi, sınırdan otomatik giriş hakkı sağlamaz.', 6),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya Schengen vizesi ne kadar süreyle verilir?', 'İspanya tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat amacı, seyahat geçmişi ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. Vizenin geçerlilik süresi ve giriş hakkı, başvuruyu değerlendiren yetkili makamların kararı doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vize başvuruları en çok hangi nedenlerle reddedilir?', 'İspanya vize başvurularının reddedilmesinde; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının ve koşullarının yeterince belgelenememesi, finansal durumun yeterli görülmemesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İspanya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'İspanya vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. İspanya''nın resmi prosedüründe ret kararı yazılı olarak bildirilir ve başvuru sahibine belirli süreler içinde itiraz yolları da tanınır.', 9),
  ((SELECT id FROM countries WHERE slug = 'ispanya'), 'İlk girişimi İspanya''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi İspanya''dan aldıysanız, seyahatinizin ana destinasyonunun İspanya olması gerekir. Schengen vizesi başvurusu, seyahatin tek veya ana destinasyonu olan ülkeye yapılmalıdır.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla İsviçre''ye gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Aile Ziyareti Vizesi', 'İsviçre''de yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Aile Birleşimi Vizesi', 'İsviçre''de yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Öğrenci Vizesi', 'İsviçre''de üniversite eğitimi veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Çalışma Vizesi', 'İsviçre''de bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Transit Vizesi', 'İsviçre üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Havaalanı Transit (A Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'İsviçre''de düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'Vize Türünün Belirlenmesi', 'İsviçre vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'Form ve Evrak Hazırlığı', 'İsviçre vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. İsviçre''nin yetkili makamları gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. İsviçre''nin Türkiye''deki resmî bilgilendirmesine göre başvurunun planlanan seyahatten en geç 15 gün önce yapılması gerekir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun yetkili makamlara ulaşmasının ardından genellikle 15 takvim günü içerisinde sonuçlandırılır. Ancak ek belge talep edilmesi veya başvurunun daha ayrıntılı incelemeye alınması durumunda bu süre uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vize ücreti ne kadar?', 'İsviçre vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'İsviçre vize başvurusunda seyahat süresince yeterli maddi imkâna sahip olduğunuzu gösteren belgelerin sunulması gerekir. Başvurunuz değerlendirilirken yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak son 59 ay içinde herhangi bir Schengen ülkesi için biyometrik veri verdiyseniz, bu veriler geçerliliğini koruyorsa yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin geçerlilik süresi dolmuşsa, başvuru merkezine şahsen giderek parmak izi vermeniz gerekir. İsviçre''nin resmî bilgilendirmesinde de Schengen başvurularında biyometrik verilerin alınması öngörülmektedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'İsviçre tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya seyahatinizin ana hedefini oluşturan ülkenin İsviçre olması gerekir. Ayrıca pasaport kontrolünde seyahat amacınızı ve planınızı kanıtlayan belgeleri (otel rezervasyonu, dönüş bileti vb.) yanınızda taşımanız önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre Schengen vizesi ne kadar süreyle verilir?', 'İsviçre tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, olumlu Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vize başvuruları en çok hangi nedenlerle reddedilir?', 'İsviçre vize başvurularının reddedilmesindeki en yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İsviçre vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'İsviçre vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'isvicre'), 'İlk girişimi İsviçre''den yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi İsviçre''den aldıysanız, seyahatinizin en uzun süren kısmını İsviçre''de geçirmeli veya seyahatinizin ana hedefi İsviçre olmalıdır.', 10);
