  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya Öğrenci Vizesi', 'İtalya''da üniversite eğitimi, dil kursu veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya Çalışma Vizesi', 'İtalya''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya Transit Vizesi', 'İtalya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği transit vize türüdür.', 6),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'İtalya''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
