  ((SELECT id FROM countries WHERE slug = 'italya'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. İtalya''nın yetkili konsolosluk makamları gerekli gördüğü durumlarda ek belge veya açıklama talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vize kararı, başvuruyu değerlendiren yetkili İtalyan makamları tarafından verilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vizesi kaç günde sonuçlanır?', 'İtalya Schengen vize başvurularının sonuçlanma süresi, başvurunun niteliğine, dönemsel yoğunluğa ve gerekli görülmesi hâlinde ek belge veya inceleme talep edilmesine göre değişebilir. Bu nedenle kesin bir sonuçlanma süresi garanti edilemez. Seyahat planınızı riske atmamak için başvurunuzu son güne bırakmamanız önerilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vize ücreti ne kadar?', 'İtalya vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak güncel konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'İtalya vize başvurusunda seyahat süreniz boyunca ulaşım, konaklama ve diğer masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Bununla birlikte yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin yeniden alınması gerekiyorsa, başvuru merkezine şahsen giderek biyometrik işlemlerinizi tamamlamanız gerekir. Gerekli görülen durumlarda İtalya makamları başvuru sahibinden yeniden biyometrik işlem talep edebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'İtalya tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya ana hedefiniz olan ülkenin İtalya olması gerekir. Ayrıca seyahat planınızın vize başvurusu sırasında sunduğunuz bilgilerle uyumlu olması önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya Schengen vizesi ne kadar süreyle verilir?', 'İtalya tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, uygun Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vize başvuruları en çok hangi nedenlerle reddedilir?', 'İtalya vize başvurularının reddedilmesindeki yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İtalya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'İtalya vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'italya'), 'İlk girişimi İtalya''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi İtalya''dan aldıysanız, seyahatinizin en uzun süren kısmını İtalya''da geçirmeli veya seyahatinizin ana hedefi İtalya olmalıdır. Vize başvurusunda sunduğunuz seyahat planının gerçek seyahatinizle uyumlu olması önemlidir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla İzlanda''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Aile Ziyareti Vizesi', 'İzlanda''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Aile Birleşimi', 'İzlanda''da yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan oturum izni sürecidir. Oturum izni onaylandıktan sonra, vizeye tabi kişiler için İzlanda''ya giriş vizesi düzenlenebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Öğrenci Vizesi', 'İzlanda''da eğitim amacıyla uzun süreli bulunmak isteyen kişilerin ilgili oturum izni için başvurması gerekir. Oturum izni onaylandıktan sonra, vizeye tabi kişiler için İzlanda''ya giriş vizesi düzenlenebilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Çalışma Vizesi', 'İzlanda''da çalışmak isteyen kişilerin, çalışma hakkı sağlayan ilgili oturum izni ve çalışma izni süreçlerini tamamlaması gerekir. Oturum izni onaylandıktan sonra, vizeye tabi kişiler için İzlanda''ya giriş vizesi düzenlenebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Transit Vizesi', 'İzlanda üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği havaalanı transit vizesidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'İzlanda''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'Vize Türünün Belirlenmesi', 'İzlanda vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'Form ve Evrak Hazırlığı', 'İzlanda vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri uygulanır. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Yetkili makamlar gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru sürecinin yürütüldüğü kanal aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vizesi kaç günde sonuçlanır?', 'Schengen vize başvurularında değerlendirme süresi normal şartlarda yaklaşık iki hafta olabilir. Ancak ek belge talep edilmesi veya başvurunun daha ayrıntılı incelenmesi gereken durumlarda bu süre uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vize ücreti ne kadar?', 'İzlanda vize başvuru ücreti, başvurulan vize türüne ve başvuru sahibinin durumuna göre değişiklik gösterebilir. Ayrıca yetkili başvuru merkezi tarafından hizmet bedeli alınabilir. Başvuru öncesinde güncel ücretlerin kontrol edilmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'İzlanda vize başvurusunda seyahat süresince ulaşım, konaklama ve diğer masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Finansal durumunuz değerlendirilirken geliriniz, banka hesap hareketleriniz ve sunduğunuz diğer belgeler birlikte dikkate alınabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen vize başvurularında pasaportunuzun planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması ve en az 2 boş sayfa içermesi gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır. Daha önceki bir Schengen vize başvurusunda alınan parmak izlerinin geçerli olduğu durumlarda yeniden parmak izi alınması gerekmeyebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'İzlanda tarafından verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken seyahatinizin ana destinasyonunun İzlanda olması veya Schengen kurallarına göre İzlanda''nın başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda Schengen vizesi ne kadar süreyle verilir?', 'İzlanda tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat amacı, seyahat geçmişi ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. Vizenin geçerlilik süresi ve giriş sayısı yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vize başvuruları en çok hangi nedenlerle reddedilir?', 'İzlanda vize başvurularının reddedilmesinde; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İzlanda vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'İzlanda vize başvurunuzun reddedilmesi, yeni bir başvuru yapılmasına engel değildir. Ancak yeni bir başvuru öncesinde ret gerekçesinin dikkatle değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'izlanda'), 'İlk girişimi İzlanda''dan yapmak zorunda mıyım?', 'Schengen vize başvurularında başvuru yapılacak ülke, seyahatin ana destinasyonuna göre belirlenir. İzlanda''dan alınan bir Schengen vizesiyle başka bir Schengen ülkesinden giriş yapılması tek başına vizeyi geçersiz hâle getirmez; ancak seyahat planınızın vizenin verildiği ülkeyi ana destinasyon olarak göstermesi gerekir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
