  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya Aile Ziyareti Vizesi', 'Letonya''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya Aile Birleşimi Vizesi', 'Letonya''da yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan uzun süreli vize ve ilgili oturum izni sürecidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya Öğrenci Vizesi', 'Letonya''da eğitim amacıyla uzun süreli bulunmak isteyen kişilerin başvurabileceği Ulusal (D Tipi) vize ve ilgili oturum izni sürecidir.', 4),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya Çalışma Vizesi', 'Letonya''da çalışmak isteyen kişilerin başvurabileceği Ulusal (D Tipi) vize ve ilgili çalışma veya oturum izni sürecidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya Transit Vizesi', 'Letonya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği transit vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Letonya''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Vize Türünün Belirlenmesi', 'Letonya vize başvurusu, seyahat amacına uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Form ve Evrak Hazırlığı', 'Başvuru formu doldurulur ve seyahat amacını ve planını destekleyen gerekli belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde yetkili başvuru merkezine gidilerek belgeler teslim edilir ve gerekli biyometrik işlemler gerçekleştirilir. Daha önceki bir Schengen başvurusunda alınan biyometrik veriler geçerli olduğu sürece yeniden parmak izi verilmesi gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Değerlendirme Süreci', 'Başvuru dosyası teslim edildikten sonra yetkili makamlar tarafından değerlendirilir. Gerekli görülmesi halinde ek belge veya bilgi talep edilebilir. Kısa süreli Schengen vize başvurularında değerlendirme normal şartlarda 15 takvim günü içinde tamamlanır; bireysel durumlarda bu süre 45 takvim gününe kadar uzayabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaport başvuru sürecinin yürütüldüğü kanal aracılığıyla teslim edilir.', 4);
