  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya Schengen vizesi ne kadar süreyle verilir?', 'Letonya tarafından verilen Schengen vizelerinin geçerlilik süresi ve giriş sayısı, başvuru sahibinin seyahat amacı ve başvuru dosyasının değerlendirilmesine göre belirlenir. Vizenin geçerlilik süresi ve izin verilen kalış süresi vize etiketinde belirtilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya vize başvuruları en çok hangi nedenlerle reddedilir?', 'Letonya vize başvurularının reddedilmesinde başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'letonya'), 'Letonya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Letonya vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Yeni bir başvuru öncesinde ret gerekçesinin dikkatle değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
