  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn Çalışma Vizesi', 'Lihtenştayn''da çalışmak isteyen kişilerin, gerekli çalışma ve oturum izinleri kapsamında başvurabileceği ulusal vize sürecidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn Transit Vizesi', 'Schengen bölgesine giriş yapmadan Lihtenştayn''a ulaşmak için kullanılan güzergâha bağlı olarak transit vize gerekliliği bulunan yolcuların başvurması gereken transit vizedir.', 6),
