  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Vize Türünün Belirlenmesi', 'Lihtenştayn vize başvurusu, seyahat amacına uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Form ve Evrak Hazırlığı', 'Başvuru formu doldurulur ve seyahat amacını ve planını destekleyen gerekli belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Kısa süreli Schengen vize başvurularında randevu alınarak VFS Global başvuru merkezine gidilir ve belgeler teslim edilir. Gerekli biyometrik işlemler başvuru sırasında gerçekleştirilir. Daha önceki bir Schengen başvurusunda alınan biyometrik veriler geçerli olduğu sürece yeniden parmak izi verilmesi gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Değerlendirme Süreci', 'Başvuru dosyası teslim edildikten sonra yetkili makamlar tarafından değerlendirilir. Gerekli görülmesi halinde ek belge veya bilgi talep edilebilir. Schengen vize başvurularında değerlendirme normal şartlarda 15 takvim günü içinde tamamlanır; bireysel durumlarda bu süre uzayabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaport başvuru sürecinin yürütüldüğü kanal aracılığıyla teslim edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu ve değerlendirme sürecini göz önünde bulundurarak başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vizesi kaç günde sonuçlanır?', 'Lihtenştayn adına yürütülen Schengen vize başvuruları normal şartlarda yaklaşık 15 takvim günü içinde sonuçlandırılır. Başvurunun daha ayrıntılı incelenmesi veya ek belge talep edilmesi gereken durumlarda değerlendirme süresi uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vize ücreti ne kadar?', 'Lihtenştayn vize başvuru ücreti, başvuru türüne ve başvuru sahibinin durumuna göre değişiklik gösterebilir. Başvuru öncesinde güncel vize ücreti ve varsa başvuru merkezi hizmet bedelinin kontrol edilmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Lihtenştayn vize başvurusunda seyahat süresince masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Finansal durumunuz, sunduğunuz belgeler ve seyahat planınızla birlikte değerlendirilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun planlanan Schengen bölgesinden ayrılış tarihinizden itibaren en az 3 ay daha geçerli olması ve son 10 yıl içinde düzenlenmiş olması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır. Daha önceki bir Schengen başvurusunda alınan biyometrik veriler geçerli olduğu sürece yeniden parmak izi vermeniz gerekmeyebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Lihtenştayn adına verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken Schengen kurallarına göre seyahatinizin ana destinasyonunun Lihtenştayn olması veya Lihtenştayn''ın başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn Schengen vizesi ne kadar süreyle verilir?', 'Lihtenştayn adına verilen Schengen vizelerinin geçerlilik süresi ve giriş sayısı, başvuru sahibinin seyahat amacı ve başvuru dosyasının değerlendirilmesine göre belirlenir. Vizenin geçerlilik süresi ve izin verilen kalış süresi vize etiketinde belirtilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vize başvuruları en çok hangi nedenlerle reddedilir?', 'Lihtenştayn vize başvurularının reddedilmesinde başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya vize şartlarının karşılanmadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'Lihtenştayn vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Lihtenştayn vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Yeni bir başvuru öncesinde ret gerekçesinin değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'lihtenstayn'), 'İlk girişimi Lihtenştayn''dan yapmak zorunda mıyım?', 'İlk girişinizi Lihtenştayn''dan yapmak her durumda zorunlu değildir. Ancak Schengen vizesi başvurusu yapılırken seyahatinizin ana destinasyonunun Lihtenştayn olması ve başvuruda sunduğunuz seyahat planının gerçek seyahatinizle uyumlu olması gerekir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Litvanya Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Litvanya''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Litvanya Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı ve ticari faaliyetler amacıyla Litvanya''ya yapılacak kısa süreli seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Litvanya Aile Ziyareti Vizesi', 'Litvanya''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Litvanya Aile Birleşimi Vizesi', 'Litvanya''da yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan ulusal vize veya ilgili oturum izni sürecidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Litvanya Öğrenci Vizesi', 'Litvanya''da eğitim amacıyla uzun süreli bulunmak isteyen kişilerin başvurabileceği ulusal vize veya ilgili oturum izni sürecidir.', 4),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Litvanya Çalışma Vizesi', 'Litvanya''da çalışmak isteyen kişilerin, çalışma amacı ve kalış süresine göre ulusal vize veya ilgili oturum izni kapsamında başvurması gereken vize sürecidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Litvanya Transit Vizesi', 'Litvanya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği transit vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Litvanya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Litvanya''da düzenlenen fuar, kongre, konferans ile kültürel, bilimsel veya sportif etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Vize Türünün Belirlenmesi', 'Litvanya vize başvurusu, seyahat amacına uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Form ve Evrak Hazırlığı', 'Başvuru formu doldurulur ve seyahat amacını ve planını destekleyen gerekli belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Schengen vize başvurusu için VFS Global üzerinden randevu alınır ve randevu tarihinde başvuru merkezine gidilerek belgeler teslim edilir. Başvurular kural olarak şahsen yapılır ve gerekli biyometrik işlemler gerçekleştirilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Değerlendirme Süreci', 'Başvuru dosyası teslim edildikten sonra Litvanya Büyükelçiliği tarafından değerlendirilir. Gerekli görülmesi halinde ek belge veya bilgi talep edilebilir. Schengen vize başvurularında değerlendirme normal şartlarda 15 takvim günü içinde tamamlanır; daha ayrıntılı inceleme veya ek belge gerektiren durumlarda bu süre 45 takvim gününe kadar uzayabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'litvanya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaport başvuru sürecinin yürütüldüğü kanal aracılığıyla teslim edilir.', 4);
