INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Macaristan''a gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Aile Ziyareti Vizesi', 'Macaristan''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Aile Birleşimi Vizesi', 'Macaristan''da yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Öğrenci Vizesi', 'Macaristan''da üniversite eğitimi veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Çalışma Vizesi', 'Macaristan''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Transit Vizesi', 'Macaristan üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Havaalanı Transit (A Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Macaristan''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Vize Türünün Belirlenmesi', 'Macaristan vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Form ve Evrak Hazırlığı', 'Macaristan vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Konsolosluk gerekli gördüğü durumlarda ek belge talep edebilir veya başvuru sahibiyle mülakat gerçekleştirebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun yetkili makama ulaşmasının ardından genellikle 15 takvim günü içerisinde sonuçlandırılır. Ancak ek belge talep edilmesi, başvurunun detaylı incelemeye alınması veya gerekli görülmesi hâlinde mülakat yapılması durumunda bu süre uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vize ücreti ne kadar?', 'Macaristan vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Macaristan vize başvurusunda seyahat süresince yeterli maddi imkâna sahip olduğunuzu gösteren belgelerin sunulması gerekir. Başvurunuz değerlendirilirken yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak son 59 ay içinde herhangi bir Schengen ülkesi için biyometrik veri verdiyseniz, bu veriler geçerliliğini koruyorsa yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin geçerlilik süresi dolmuşsa, başvuru merkezine şahsen giderek parmak izi vermeniz gerekir. Macaristan''ın Türkiye''deki resmî bilgilendirmesinde de son 59 ay içinde parmak izi vermemiş başvuru sahipleri için şahsen başvuru esası belirtilmektedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Macaristan tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya seyahatinizin ana amacını oluşturan ülkenin Macaristan olması gerekir. Ayrıca pasaport kontrolünde seyahat amacınızı ve planınızı kanıtlayan belgeleri (otel rezervasyonu, dönüş bileti vb.) yanınızda taşımanız önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan Schengen vizesi ne kadar süreyle verilir?', 'Macaristan tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, olumlu Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen yetkili makamların değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vize başvuruları en çok hangi nedenlerle reddedilir?', 'Macaristan vize başvurularının reddedilmesindeki en yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır. Macaristan''ın resmî bilgilendirmesinde de seyahat amacının ve koşullarının kanıtlanamaması ile yeterli geçim kaynağının gösterilememesi ret nedenleri arasında sayılmaktadır.', 8),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'Macaristan vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Macaristan vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'macaristan'), 'İlk girişimi Macaristan''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Macaristan''dan aldıysanız, seyahatinizin en uzun süren kısmını Macaristan''da geçirmeli veya seyahatinizin ana hedefi Macaristan olmalıdır.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Malta''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve diğer ticari faaliyetler amacıyla Malta''ya yapılacak kısa süreli seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Aile Ziyareti Vizesi', 'Malta''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Aile Birleşimi Vizesi', 'Malta''da yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan uzun süreli vize ve ilgili oturum izni sürecidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Öğrenci Vizesi', 'Malta''da eğitim amacıyla 90 günden uzun süre bulunmak isteyen kişilerin başvurabileceği Ulusal (D Tipi) vize sürecidir.', 4),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Çalışma Vizesi', 'Malta''da çalışmak isteyen kişilerin, çalışma amacı ve kalış süresine göre başvurması gereken uzun süreli vize ve ilgili izin sürecidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Transit Vizesi', 'Malta üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği transit vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Malta''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Vize Türünün Belirlenmesi', 'Malta vize başvurusu, seyahat amacına ve kalış süresine uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Form ve Evrak Hazırlığı', 'Başvuru formu doldurulur ve seyahat amacını ve planını destekleyen gerekli belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Kısa süreli Schengen vize başvurularında başvuru formu doldurulur ve seyahat amacını ve planını destekleyen gerekli belgeler hazırlanır. VFS Global üzerinden randevu alınarak randevu tarihinde başvuru merkezine gidilir ve belgeler teslim edilir. Biyometrik işlemler de başvuru sırasında gerçekleştirilir. Daha önceki bir Schengen başvurusunda alınan biyometrik veriler geçerli olduğu sürece yeniden parmak izi verilmesi gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Değerlendirme Süreci', 'Başvuru dosyası teslim edildikten sonra Malta''nın yetkili makamları tarafından değerlendirilir. Gerekli görülmesi halinde ek belge veya bilgi talep edilebilir. Malta''nın resmî bilgilerine göre başvurular planlanan seyahatten en erken 6 ay, denizciler için ise belirli koşullarda 9 ay önce sunulabilir ve normal başvuru için seyahatten en geç 15 takvim günü önce başvuru yapılması gerekir.', 3),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaport başvuru sürecinin yürütüldüğü kanal aracılığıyla teslim edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vize başvurusunu ne kadar önce yapmalıyım?', 'Malta Schengen vize başvuruları planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Başvurunun seyahatten en geç 15 takvim günü önce sunulması gerekir. Randevu ve değerlendirme sürecini göz önünde bulundurarak başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vizesi kaç günde sonuçlanır?', 'Malta Schengen vize başvurularında değerlendirme süresi başvurunun niteliğine ve gerekli incelemelere göre değişebilir. Ek belge veya ayrıntılı inceleme gereken durumlarda değerlendirme süresi uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vize ücreti ne kadar?', 'Malta vize başvuru ücreti, başvuru türüne ve başvuru sahibinin durumuna göre değişiklik gösterebilir. Başvuru öncesinde güncel vize ücreti ve varsa başvuru merkezi hizmet bedelinin kontrol edilmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Malta vize başvurusunda seyahat süresince masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Finansal durumunuz, sunduğunuz belgeler ve seyahat planınızla birlikte değerlendirilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun planlanan Schengen bölgesinden ayrılış tarihinizden itibaren en az 3 ay daha geçerli olması ve ilgili Schengen pasaport koşullarını karşılaması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır. Daha önceki bir Schengen başvurusunda alınan biyometrik veriler geçerli olduğu sürece yeniden parmak izi verilmesi gerekmeyebilir. Malta''nın resmî bilgilerine göre biyometrik veriler başvuru sırasında alınır.', 5),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Malta tarafından verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken Schengen kurallarına göre seyahatinizin ana destinasyonunun Malta olması veya Malta''nın başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta Schengen vizesi ne kadar süreyle verilir?', 'Malta tarafından verilen Schengen vizelerinin geçerlilik süresi ve giriş sayısı başvuru sahibinin durumuna ve yetkili makamların değerlendirmesine göre belirlenir. Vizenin geçerlilik süresi ve izin verilen kalış süresi vize etiketinde belirtilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vize başvuruları en çok hangi nedenlerle reddedilir?', 'Malta vize başvurularının reddedilmesinde başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'Malta vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Malta vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Yeni bir başvuru öncesinde ret gerekçesinin değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'malta'), 'İlk girişimi Malta''dan yapmak zorunda mıyım?', 'İlk girişinizi Malta''dan yapmak her durumda zorunlu değildir. Ancak Schengen vizesi başvurusu yapılırken seyahatinizin ana destinasyonunun Malta olması ve başvuruda sunduğunuz seyahat planının gerçek seyahatinizle uyumlu olması gerekir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Norveç''e gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve diğer ticari faaliyetler amacıyla Norveç''e yapılacak kısa süreli seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Aile Ziyareti Vizesi', 'Norveç''te yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Aile Birleşimi Vizesi', 'Norveç''te yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan oturum izni ve buna bağlı vize sürecidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Öğrenci Vizesi', 'Norveç''te eğitim amacıyla uzun süreli bulunmak isteyen kişilerin başvurması gereken oturum izni sürecidir.', 4),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Çalışma Vizesi', 'Norveç''te çalışmak isteyen kişilerin, çalışma koşullarına göre başvurması gereken oturum izni sürecidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Transit Vizesi', 'Norveç üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği transit vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Norveç''te düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Vize Türünün Belirlenmesi', 'Norveç vize başvurusu, seyahat amacına ve kalış süresine uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Form ve Evrak Hazırlığı', 'Kısa süreli Schengen vize başvurularında çevrim içi başvuru formu doldurulur ve başvuru ücreti çevrim içi sistem üzerinden ödenir. Başvuru formu ve ödeme bilgileri alındıktan sonra gerekli belgeler hazırlanır ve VFS Global üzerinden randevu alınır.', 1),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezine gidilerek pasaport ve belgeler teslim edilir. Gerekli biyometrik işlemler de başvuru sırasında gerçekleştirilir. Daha önce alınmış biyometrik veriler geçerli olduğu sürece yeniden parmak izi verilmesi gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Değerlendirme Süreci', 'Başvuru dosyası VFS Global tarafından Norveç makamlarına iletildikten sonra değerlendirme süreci başlar. Gerekli görülmesi halinde ek belge veya bilgi talep edilebilir. Başvurular normal şartlarda 15 takvim günü içinde sonuçlandırılır; bazı dosyalarda değerlendirme süresi 45 takvim gününe kadar uzayabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaport başvuru sürecinin yürütüldüğü kanal aracılığıyla teslim edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu ve değerlendirme sürecini göz önünde bulundurarak başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vizesi kaç günde sonuçlanır?', 'Norveç Schengen vize başvuruları normal şartlarda 15 takvim günü içinde sonuçlandırılır. Başvurunun daha ayrıntılı incelenmesi veya ek belge talep edilmesi gereken durumlarda değerlendirme süresi 45 takvim gününe kadar uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vize ücreti ne kadar?', 'Norveç vize başvuru ücreti, başvuru türüne ve başvuru sahibinin durumuna göre değişiklik gösterebilir. Başvuru öncesinde güncel vize ücreti ve varsa başvuru merkezi hizmet bedelinin kontrol edilmesi gerekir. Norveç''te vize başvuru ücreti çevrim içi başvuru sırasında ödenir; VFS Global ayrıca hizmet bedeli uygulayabilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Norveç vize başvurusunda seyahat süresince masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Finansal durumunuz, sunduğunuz belgeler ve seyahat planınızla birlikte değerlendirilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun planlanan Schengen bölgesinden ayrılış tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca başvuruda sunulan pasaportun ilgili Schengen seyahat belgesi koşullarını karşılaması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır. Daha önce alınmış biyometrik veriler geçerli olduğu sürece yeniden parmak izi verilmesi gerekmeyebilir. Norveç''in Türkiye''deki başvuru sürecinde biyometrik işlemler VFS Global başvuru merkezlerinde gerçekleştirilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Norveç tarafından verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken Schengen kurallarına göre seyahatinizin ana destinasyonunun Norveç olması veya Norveç''in başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç Schengen vizesi ne kadar süreyle verilir?', 'Norveç tarafından verilen Schengen vizelerinin geçerlilik süresi ve giriş sayısı başvuru sahibinin seyahat amacı ve başvuru dosyasının değerlendirilmesine göre belirlenir. Vizenin geçerlilik süresi ve izin verilen kalış süresi vize etiketinde belirtilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vize başvuruları en çok hangi nedenlerle reddedilir?', 'Norveç vize başvurularının reddedilmesinde başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'Norveç vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Norveç vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Yeni bir başvuru öncesinde ret gerekçesinin değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'norvec'), 'İlk girişimi Norveç''ten yapmak zorunda mıyım?', 'İlk girişinizi Norveç''ten yapmak her durumda zorunlu değildir. Ancak Schengen vizesi başvurusu yapılırken seyahatinizin ana destinasyonunun Norveç olması ve başvuruda sunduğunuz seyahat planının gerçek seyahatinizle uyumlu olması gerekir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Polonya''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve diğer ticari faaliyetler amacıyla Polonya''ya yapılacak kısa süreli seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Aile Ziyareti Vizesi', 'Polonya''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Aile Birleşimi Vizesi', 'Polonya''da yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vize ve ilgili oturum izni sürecidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Öğrenci Vizesi', 'Polonya''da eğitim amacıyla uzun süreli bulunmak isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Çalışma Vizesi', 'Polonya''da çalışmak isteyen kişilerin, çalışma amacı ve koşullarına göre başvurması gereken Ulusal (D Tipi) vize sürecidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Transit Vizesi', 'Polonya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği transit vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Polonya''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Vize Türünün Belirlenmesi', 'Polonya vize başvurusu, seyahat amacına ve kalış süresine uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Form ve Evrak Hazırlığı', 'Kısa süreli Schengen vize başvurularında e-Konsulat sistemi üzerinden başvuru formu doldurulur ve gerekli belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Başvuru kategorisine uygun şekilde VFS Global üzerinden randevu alınır. Randevu tarihinde başvuru merkezine şahsen gidilerek belgeler ve pasaport teslim edilir, gerekli biyometrik işlemler gerçekleştirilir. Son 59 ay içinde alınmış geçerli Schengen parmak izi kaydı bulunan başvuru sahiplerinin yeniden parmak izi vermesi gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Değerlendirme Süreci', 'Başvuru dosyası Vize Başvuru Merkezi aracılığıyla Polonya''nın yetkili konsolosluk makamına iletilir ve değerlendirilir. Gerekli görülmesi halinde ek belge veya bilgi talep edilebilir. Başvurular normal şartlarda 15 takvim günü içinde karara bağlanır; başvurunun daha ayrıntılı incelenmesi gereken durumlarda bu süre 45 takvim gününe kadar uzayabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaport başvurunun yapıldığı Vize Başvuru Merkezi aracılığıyla teslim edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
