  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya vizesi kaç günde sonuçlanır?', 'Polonya Schengen vize başvuruları normal şartlarda 15 takvim günü içinde sonuçlandırılır. Başvurunun daha ayrıntılı incelenmesi gereken durumlarda değerlendirme süresi 45 takvim gününe kadar uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya vize ücreti ne kadar?', 'Polonya vize başvuru ücreti, başvuru türüne ve başvuru sahibinin durumuna göre değişiklik gösterebilir. Başvuru öncesinde güncel vize ücreti ve varsa başvuru merkezi hizmet bedelinin kontrol edilmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Polonya vize başvurusunda seyahat süresince masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Finansal durumunuz, sunduğunuz belgeler ve seyahat planınızla birlikte değerlendirilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun talep edilen vizenin sona erme tarihinden sonra en az 3 ay daha geçerli olması, son 10 yıl içinde düzenlenmiş olması ve vize işlemleri için yeterli boş sayfa içermesi gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır. Son 59 ay içinde alınmış geçerli bir Schengen parmak izi kaydı bulunan başvuru sahiplerinin yeniden parmak izi vermesi gerekmeyebilir. 12 yaşından küçük çocuklar ve biyometrik veri alınmasının fiziksel olarak mümkün olmadığı kişiler belirli koşullarda parmak izi işleminden muaftır.', 5),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Polonya tarafından verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken Schengen kurallarına göre seyahatinizin ana destinasyonunun Polonya olması veya Polonya''nın başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya Schengen vizesi ne kadar süreyle verilir?', 'Polonya tarafından verilen Schengen vizelerinin geçerlilik süresi ve giriş sayısı, başvuru sahibinin seyahat amacı ve başvuru dosyasının değerlendirilmesine göre belirlenir. Vizenin geçerlilik süresi ve izin verilen kalış süresi vize etiketinde belirtilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya vize başvuruları en çok hangi nedenlerle reddedilir?', 'Polonya vize başvurularının reddedilmesinde başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'Polonya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Polonya vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Yeni bir başvuru öncesinde ret gerekçesinin değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'polonya'), 'İlk girişimi Polonya''dan yapmak zorunda mıyım?', 'İlk girişinizi Polonya''dan yapmak her durumda zorunlu değildir. Ancak Schengen vizesi başvurusu yapılırken seyahatinizin ana destinasyonunun Polonya olması ve başvuruda sunduğunuz seyahat planının gerçek seyahatinizle uyumlu olması gerekir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Portekiz''e gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Aile Ziyareti Vizesi', 'Portekiz''de yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Aile Birleşimi Vizesi', 'Portekiz''de yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Öğrenci Vizesi', 'Portekiz''de üniversite eğitimi, dil kursu veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Çalışma Vizesi', 'Portekiz''de bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Transit Vizesi', 'Portekiz üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Schengen (C Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Portekiz''de düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Vize Türünün Belirlenmesi', 'Portekiz vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Form ve Evrak Hazırlığı', 'Portekiz vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Konsolosluk veya yetkili makamlar gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun konsolosluğa ulaşmasının ardından genellikle 15 takvim günü içerisinde sonuçlandırılır. Ancak ek belge talep edilmesi, yoğun başvuru dönemleri veya başvurunun detaylı incelemeye alınması durumunda bu süre uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vize ücreti ne kadar?', 'Portekiz vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Portekiz Konsolosluğu tarafından belirlenmiş resmi bir minimum banka bakiyesi bulunmamaktadır. Başvurunuz değerlendirilirken hesabınızda, seyahat süreniz boyunca ulaşım, konaklama ve diğer masraflarınızı karşılayabilecek yeterli finansal kaynağın bulunması beklenir. Bununla birlikte yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak son 59 ay içinde herhangi bir Schengen ülkesi için biyometrik veri verdiyseniz, bu veriler geçerliliğini koruyorsa yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin geçerlilik süresi dolmuşsa, başvuru merkezine şahsen giderek parmak izi vermeniz gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Portekiz tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya ana giriş yapacağınız ülkenin Portekiz olması gerekir. Ayrıca pasaport kontrolünde seyahat amacınızı ve planınızı kanıtlayan belgeleri (otel rezervasyonu, dönüş bileti vb.) yanınızda taşımanız önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz Schengen vizesi ne kadar süreyle verilir?', 'Portekiz tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, olumlu Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen konsolosluğun değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vize başvuruları en çok hangi nedenlerle reddedilir?', 'Portekiz vize başvurularının reddedilmesindeki en yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'Portekiz vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Portekiz vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'portekiz'), 'İlk girişimi Portekiz''den yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Portekiz''den aldıysanız, seyahatinizin en uzun süren kısmını Portekiz''de geçirmeli veya seyahatinizin ana hedefi Portekiz olmalıdır.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Romanya''ya gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve diğer ticari faaliyetler amacıyla Romanya''ya yapılacak kısa süreli seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Aile Ziyareti Vizesi', 'Romanya''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Aile Birleşimi Vizesi', 'Romanya''da yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vize ve ilgili oturum izni sürecidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Öğrenci Vizesi', 'Romanya''da eğitim amacıyla uzun süreli bulunmak isteyen kişilerin başvurabileceği Ulusal (D Tipi) vize ve ilgili oturum izni sürecidir.', 4),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Çalışma Vizesi', 'Romanya''da çalışmak isteyen kişilerin, çalışma ve oturum koşullarına göre başvurması gereken Ulusal (D Tipi) vize sürecidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Transit Vizesi', 'Romanya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği transit vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Romanya''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Vize Türünün Belirlenmesi', 'Romanya vize başvurusu, seyahat amacına ve kalış süresine uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Form ve Evrak Hazırlığı', 'Başvuru, Romanya Dışişleri Bakanlığı''nın eViza portalı üzerinden online olarak başlatılır. Başvuru sahibi, seyahat amacı, vatandaşlık ve seyahat belgesi gibi bilgileri girerek başvuru formunu doldurur ve gerekli belgeleri elektronik ortamda sisteme yükler.', 1),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde gerekli belgeler ve pasaportla birlikte yetkili Romanya diplomatik misyonu veya konsolosluk birimine gidilir. Gerekli biyometrik işlemler gerçekleştirilir ve başvuru dosyası teslim edilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Değerlendirme Süreci', 'Başvuru sonrasında Romanya makamları tarafından değerlendirme yapılır; gerekli görülmesi halinde ek belge veya bilgi talep edilebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Sonuç ve Pasaport Teslimi', 'Karar tamamlandığında pasaport başvuru sürecinin yürütüldüğü kanal aracılığıyla teslim edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu ve değerlendirme sürecini göz önünde bulundurarak başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vizesi kaç günde sonuçlanır?', 'Romanya Schengen vize başvurularında değerlendirme süresi başvurunun niteliğine ve gerekli incelemelere göre değişebilir. Ek belge veya ayrıntılı inceleme gereken durumlarda değerlendirme süresi uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vize ücreti ne kadar?', 'Romanya vize başvuru ücreti, başvuru türüne ve başvuru sahibinin durumuna göre değişiklik gösterebilir. Başvuru öncesinde güncel vize ücretinin ve varsa ilgili hizmet bedellerinin kontrol edilmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Romanya vize başvurusunda seyahat süresince masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Finansal durumunuz, sunduğunuz belgeler ve seyahat planınızla birlikte değerlendirilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun planlanan Schengen bölgesinden ayrılış tarihinizden itibaren en az 3 ay daha geçerli olması ve ilgili Schengen seyahat belgesi koşullarını karşılaması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır. Daha önce alınmış biyometrik veriler geçerli olduğu sürece yeniden parmak izi verilmesi gerekmeyebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Romanya tarafından verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken Schengen kurallarına göre seyahatinizin ana destinasyonunun Romanya olması veya Romanya''nın başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya Schengen vizesi ne kadar süreyle verilir?', 'Romanya tarafından verilen Schengen vizelerinin geçerlilik süresi ve giriş sayısı, başvuru sahibinin seyahat amacı ve başvuru dosyasının değerlendirilmesine göre belirlenir. Vizenin geçerlilik süresi ve izin verilen kalış süresi vize etiketinde belirtilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vize başvuruları en çok hangi nedenlerle reddedilir?', 'Romanya vize başvurularının reddedilmesinde başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'Romanya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Romanya vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Yeni bir başvuru öncesinde ret gerekçesinin değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'romanya'), 'İlk girişimi Romanya''dan yapmak zorunda mıyım?', 'İlk girişinizi Romanya''dan yapmak her durumda zorunlu değildir. Ancak Schengen vizesi başvurusu yapılırken seyahatinizin ana destinasyonunun Romanya olması ve başvuruda sunduğunuz seyahat planının gerçek seyahatinizle uyumlu olması gerekir.', 10);
