  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Slovakya Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve diğer ticari faaliyetler amacıyla Slovakya''ya yapılacak kısa süreli seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Slovakya Aile Ziyareti Vizesi', 'Slovakya''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
