  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Slovakya Öğrenci Vizesi', 'Slovakya''da eğitim amacıyla uzun süreli bulunmak isteyen kişilerin başvurabileceği Ulusal (D Tipi) vize ve ilgili oturum izni sürecidir.', 4),
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Slovakya Çalışma Vizesi', 'Slovakya''da çalışmak isteyen kişilerin, çalışma amacı ve kalış süresine göre başvurması gereken Ulusal (D Tipi) vize ve ilgili oturum izni sürecidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Slovakya Transit Vizesi', 'Slovakya üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği transit vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Slovakya Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Slovakya''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Vize Türünün Belirlenmesi', 'Slovakya vize başvurusu, seyahat amacına ve kalış süresine uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Form ve Evrak Hazırlığı', 'Kısa süreli Schengen vize başvurularında başvuru formu hazırlanır ve seyahat amacını destekleyen gerekli belgeler tamamlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Başvuru sahibinin ikamet ettiği ile göre yetkili BLS International veya VFS Global başvuru merkezi üzerinden randevu alınır. Randevu tarihinde başvuru merkezine şahsen gidilerek pasaport ve belgeler teslim edilir. Gerekli biyometrik işlemler de başvuru sırasında gerçekleştirilir. Daha önce alınmış ve geçerli olan biyometrik veriler, ilgili kurallar çerçevesinde yeniden kullanılabilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Değerlendirme Süreci', 'Başvuru dosyası yetkili başvuru merkezi aracılığıyla Slovakya''nın ilgili konsolosluk makamına iletilir ve değerlendirme süreci başlar. Gerekli görülmesi halinde ek belge veya bilgi talep edilebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'slovakya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaport, başvurunun yapıldığı başvuru merkezi üzerinden teslim edilir.', 4);
