  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Form ve Evrak Hazırlığı', 'Kısa süreli Schengen vize başvurularında başvuru formu doldurulur ve seyahat amacını destekleyen gerekli belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Başvuru, Ankara''daki Slovenya Büyükelçiliği, yetkili VFS Global merkezleri veya İstanbul''daki AS Visa merkezi üzerinden yapılabilir. Başvuru sahibinin şahsen başvuru sürecine katılması ve biyometrik verilerinin alınması genel kuraldır.', 2),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Değerlendirme Süreci', 'Başvuru dosyası teslim edildikten sonra Slovenya''nın yetkili makamları tarafından değerlendirilir. Gerekli görülmesi halinde ek belge veya bilgi talep edilebilir. Başvuru, kural olarak seyahatten en az 15 takvim günü önce yapılmalı ve en erken seyahat tarihinden 6 ay önce sunulabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaport başvuru sürecinin yürütüldüğü kanal aracılığıyla teslim edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vize başvurusunu ne kadar önce yapmalıyım?', 'Slovenya Schengen vize başvuruları planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Başvurunun kural olarak seyahatten en az 15 takvim günü önce sunulması gerekir. Randevu ve değerlendirme sürecini göz önünde bulundurarak başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vizesi kaç günde sonuçlanır?', 'Slovenya Schengen vize başvurularında değerlendirme süresi başvurunun niteliğine ve gerekli incelemelere göre değişebilir. Başvurunun daha ayrıntılı incelenmesi veya ek bilgi ve belge talep edilmesi halinde süreç uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vize ücreti ne kadar?', 'Slovenya vize başvuru ücreti, başvuru sahibinin durumuna ve başvuru türüne göre değişiklik gösterebilir. Başvuru öncesinde güncel vize ücretinin ve başvuru merkezi aracılığıyla yapılan başvurularda varsa hizmet bedelinin kontrol edilmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Slovenya vize başvurusunda seyahat süresince masraflarınızı karşılayabilecek yeterli finansal kaynağa sahip olduğunuzu göstermeniz gerekir. Finansal durumunuz, sunduğunuz belgeler ve seyahat planınızla birlikte değerlendirilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun planlanan Schengen bölgesinden ayrılış tarihinizden itibaren en az 3 ay daha geçerli olması, son 10 yıl içinde düzenlenmiş olması ve en az iki boş sayfasının bulunması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veriler alınır ve başvuru sahibinin genel kural olarak şahsen başvuru yapması gerekir. Belirli kategoriler için biyometrik veri alınmasına ilişkin istisnalar bulunabilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Slovenya tarafından verilen geçerli bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak vize başvurusu yapılırken seyahatinizin ana destinasyonunun Slovenya olması veya Slovenya''nın başvuru yapılması gereken ülke olması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya Schengen vizesi ne kadar süreyle verilir?', 'Slovenya tarafından verilen Schengen vizelerinin geçerlilik süresi ve giriş sayısı, başvuru sahibinin durumuna ve yetkili makamların değerlendirmesine göre belirlenir. Vizenin geçerlilik süresi ve izin verilen kalış süresi vize etiketinde belirtilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vize başvuruları en çok hangi nedenlerle reddedilir?', 'Slovenya vize başvurularının reddedilmesinde başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, seyahat amacının yeterince belgelenmemesi, finansal yeterliliğin gösterilememesi veya başvuru sahibinin vize şartlarını karşılamadığı kanaatine varılması gibi nedenler etkili olabilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'Slovenya vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Slovenya vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Yeni bir başvuru öncesinde ret gerekçesinin değerlendirilmesi ve varsa eksikliklerin veya tutarsızlıkların giderilmesi önemlidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'slovenya'), 'İlk girişimi Slovenya''dan yapmak zorunda mıyım?', 'İlk girişinizi Slovenya''dan yapmak her durumda zorunlu değildir. Ancak Schengen vizesi başvurusu yapılırken seyahatinizin ana destinasyonunun Slovenya olması ve başvuruda sunduğunuz seyahat planının gerçek seyahatinizle uyumlu olması gerekir.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Yunanistan''a gitmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 0),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, fuar ve ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Schengen (C Tipi) vizedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Aile Ziyareti Vizesi', 'Yunanistan''da yaşayan aile bireylerini veya yakınlarını ziyaret etmek isteyen kişilerin başvurabileceği Schengen (C Tipi) vizedir.', 2),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Aile Birleşimi Vizesi', 'Yunanistan''da yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan Ulusal (D Tipi) vizedir.', 3),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Öğrenci Vizesi', 'Yunanistan''da üniversite eğitimi, dil kursu veya diğer uzun süreli eğitim programlarına katılacak kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Çalışma Vizesi', 'Yunanistan''da bir işveren yanında çalışmak, istihdam edilmek veya mesleki faaliyet yürütmek isteyen kişilerin başvurabileceği Ulusal (D Tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Transit Vizesi', 'Yunanistan üzerinden başka bir ülkeye transit geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği Schengen (C Tipi) vizedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Fuar, Kültürel Etkinlik ve Konferans Vizesi', 'Yunanistan''da düzenlenen fuar, kongre, konferans ile kültürel veya bilimsel etkinliklere katılım amacıyla başvurulan Schengen (C Tipi) vizedir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Vize Türünün Belirlenmesi', 'Yunanistan vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar. Doğru vize türü, dosyanızın tutarlılığını belirleyen ilk adımdır.', 0),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Form ve Evrak Hazırlığı', 'Yunanistan vize başvuru formu doldurulur ve seyahat planınızı destekleyen belgeler hazırlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Randevu, Evrak Teslimi ve Biyometrik İşlemler', 'Randevu tarihinde başvuru merkezinde evrak teslimi yapılır ve biyometrik işlemler gerçekleştirilir. Schengen vize başvurularında parmak izi ve biyometrik fotoğraf işlemleri zorunludur. Daha önceki Schengen başvurularınızda alınan biyometrik veriler geçerli ise yeniden parmak izi vermeniz gerekmeyebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra değerlendirme süreci başlar. Konsolosluk veya yetkili makamlar gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvuruları, planlanan seyahat tarihinden en erken 6 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 4–6 hafta önce tamamlamanız tavsiye edilir. Özellikle yoğun başvuru dönemlerinde randevu süreleri uzayabileceğinden başvurunuzu mümkün olduğunca erken planlamanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun konsolosluğa ulaşmasının ardından genellikle 15 takvim günü içerisinde sonuçlandırılır. Ancak ek belge talep edilmesi, yoğun başvuru dönemleri veya başvurunun detaylı incelemeye alınması durumunda bu süre uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vize ücreti ne kadar?', 'Yunanistan vize başvuru ücreti; başvurulan vize türüne, başvuru sahibinin yaşına ve uygulanacak konsolosluk tarifesine göre değişiklik gösterebilir. Toplam maliyet; konsolosluk harcı, yetkili başvuru merkezi hizmet bedeli ve tercih edilmesi hâlinde seyahat sağlık sigortası veya ek başvuru hizmetlerinden oluşur. Başvuru öncesinde ödenecek tüm ücret kalemlerinin güncel tutarlarını öğrenmeniz, süreci doğru planlamanız açısından önemlidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Yunanistan Konsolosluğu tarafından belirlenmiş resmi bir minimum banka bakiyesi bulunmamaktadır. Başvurunuz değerlendirilirken hesabınızda, seyahat süreniz boyunca ulaşım, konaklama ve diğer masraflarınızı karşılayabilecek yeterli finansal kaynağın bulunması beklenir. Bununla birlikte yalnızca hesap bakiyesi değil; gelir durumunuz, hesap hareketleriniz ve sunduğunuz diğer belgeler de birlikte değerlendirilir. Bu nedenle önemli olan belirli bir tutar göstermekten ziyade, finansal durumunuzun başvuru dosyanızla tutarlı olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Schengen kuralları gereği pasaportunuzun, planlanan dönüş tarihinizden itibaren en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş olması ve en az 2 boş sayfa içermesi zorunludur. Başvuru sürecinde olası sorunlarla karşılaşmamak adına, pasaportunuzun seyahat bitiş tarihinden sonra daha uzun süre geçerliliğini koruması tavsiye edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında biyometrik veri (parmak izi) verilmesi zorunludur. Ancak son 59 ay içinde herhangi bir Schengen ülkesi için biyometrik veri verdiyseniz, bu veriler geçerliliğini koruyorsa yeniden parmak izi vermeniz gerekmeyebilir. İlk kez başvuru yapıyorsanız veya biyometrik verilerinizin geçerlilik süresi dolmuşsa, başvuru merkezine şahsen giderek parmak izi vermeniz gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vizesi ile diğer Schengen ülkelerine seyahat edebilir miyim?', 'Yunanistan tarafından verilen bir Schengen vizesi ile diğer Schengen ülkelerine seyahat edebilirsiniz. Ancak kural olarak; seyahatiniz birden fazla ülkeyi kapsıyorsa en uzun konaklamayı yapacağınız veya ana destinasyonunuz olan ülkenin Yunanistan olması gerekir. Ayrıca pasaport kontrolünde seyahat amacınızı ve planınızı kanıtlayan belgeleri yanınızda taşımanız önemlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan Schengen vizesi ne kadar süreyle verilir?', 'Yunanistan tarafından verilen Schengen vizelerinin geçerlilik süresi, başvuru sahibinin seyahat geçmişi, seyahat amacı ve başvuru dosyasının değerlendirilmesine göre değişiklik gösterebilir. İlk başvurularda vize süresi çoğu zaman planlanan seyahat tarihleriyle sınırlı olurken, olumlu Schengen geçmişine sahip başvuru sahiplerine daha uzun süreli ve çok girişli vizeler verilebilmektedir. Vizenin geçerlilik süresi ve giriş hakkı tamamen konsolosluğun değerlendirmesi doğrultusunda belirlenir.', 7),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vize başvuruları en çok hangi nedenlerle reddedilir?', 'Yunanistan vize başvurularının reddedilmesindeki en yaygın nedenler arasında; başvuru dosyasındaki bilgi ve belgelerin yetersiz veya tutarsız bulunması, finansal yeterliliğin yeterince gösterilememesi, seyahat amacının açık şekilde belgelenememesi ve başvuru sahibinin ülkesine geri döneceğine ilişkin yeterli kanaat oluşmaması yer alır.', 8),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'Yunanistan vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Yunanistan vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesinin dikkatle değerlendirilmesi ve ret kararına neden olan eksiklik veya tutarsızlıkların giderilmesi önemlidir. Aynı bilgi ve belgelerle yeniden başvuru yapılması farklı bir sonuç doğurmayabilir. Bu nedenle yeni başvurunun, ret gerekçeleri dikkate alınarak daha güçlü ve tutarlı bir dosya ile hazırlanması tavsiye edilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'yunanistan'), 'İlk girişimi Yunanistan''dan yapmak zorunda mıyım?', 'İlk uçuşunuzu veya girişinizi başka bir Schengen ülkesinden yapabilirsiniz. Ancak vizeyi Yunanistan''dan aldıysanız, seyahatinizin en uzun süren kısmını Yunanistan''da geçirmeli veya seyahatinizin ana hedefi Yunanistan olmalıdır.', 10);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD Turistik ve Ticari Vizesi (B1/B2)', 'Tatil, gezi, aile/arkadaş ziyareti, tıbbi tedavi (B2) veya iş görüşmesi, konferans, fuar katılımı (B1) amacıyla yapılan seyahatler için verilen birleşik ziyaretçi vizesidir.', 0),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD Öğrenci Vizesi (F1 / M1)', 'ABD''de üniversite, dil okulu veya akademik programlara katılacak kişiler (F1) ile mesleki/teknik eğitim alacak kişiler (M1) için verilen vize türüdür.', 1),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD Değişim Programı Vizesi (J1)', 'Work and Travel, staj, akademisyen, araştırmacı veya Au Pair gibi değişim programlarına katılacak kişilerin başvurabileceği vize türüdür.', 2),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD Geçici Çalışma Vizesi (H, L, O, P Vizeleri)', 'ABD''li bir işverenden onaylı dilekçe (I-129 / I-797 PETITION) almış uzman çalışanlar, şirket içi transferler veya üstün yetenekli kişilerin başvurduğu geçici çalışma vizesidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD Transit Vizesi (C1)', 'ABD havalimanları üzerinden başka bir üçüncü ülkeye aktarmalı geçiş yapacak yolcuların ihtiyaç duyduğu vize türüdür.', 4);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'abd'), 'DS-160 Formunun Doldurulması', 'ABD vize başvurusu, DS-160 başvuru formunun eksiksiz, doğru ve İngilizce olarak doldurulmasıyla başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Randevu Oluşturulması', 'Form onaylandıktan sonra resmi randevu sistemi üzerinden profil oluşturulur ve konsolosluk mülakat randevusu alınır.', 1),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Biyometrik İşlemler ve Mülakat', 'Randevu tarihinde seçilen konsolosluğa (İstanbul veya Ankara) şahsen gidilerek biyometrik veriler teslim edilir ve ABD konsolosluk görevlisi ile birebir mülakat gerçekleştirilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Değerlendirme', 'Mülakat esnasında vize görevlisi başvurunuzu anlık olarak değerlendirir.', 3),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Sonuç ve Pasaport Teslimi', 'Vizenizin onaylanması halinde pasaportunuz teslim alınır ve basım işlemlerinin ardından PTT aracılığıyla tarafınıza gönderilir; başvurunun olumsuz sonuçlanması halinde ise pasaportunuz mülakat sonunda ret gerekçesini içeren belge ile tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vize başvurusunu ne kadar önce yapmalıyım?', 'ABD Konsolosluklarındaki randevu yoğunlukları ve bekleme süreleri dönemsel olarak değişkenlik göstermektedir. Bu nedenle seyahat planınızın aksamaması adına başvurunuzu planlanan seyahat tarihinden mümkün olduğunca erken (mümkünse aylar öncesinden) başlatmanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vizesi kaç günde sonuçlanır?', 'Mülakatınız olumlu geçtiği takdirde pasaportunuz vize basımı tamamlanarak ortalama 3-5 iş günü içerisinde seçtiğiniz PTT şubesine teslim edilir. Ek inceleme (idari işlem / Administrative Processing) kararı verilen başvurularda ise süreç uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vize ücreti ne kadardır?', 'Vize harçları; başvurulan vize türüne (B1/B2, F1, H1-B vb.) ve başvuru kategorisine göre değişiklik göstermektedir. Güncel konsolosluk MRV harçları ve danışmanlık hizmet bedellerimiz hakkında detaylı bilgi almak için ekibimizle iletişime geçebilirsiniz.', 2),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'ABD Konsolosluğu sabit bir tutar belirtmez. Mülakat esnasında temel odak noktası; seyahatinizi kendi finansal kaynaklarınızla karşılayabileceğinizi ve Türkiye''deki düzenli gelirinizi belgelendirmenizdir.', 3),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun, ABD''de kalmayı planladığınız sürenin bitiminden itibaren en az 6 ay daha geçerliliği bulunmalıdır.', 4),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Eski pasaportumdaki geçerli ABD vizesi ile yeni pasaportumla seyahat edebilir miyim?', 'Evet. Eski pasaportunuzun süresi dolmuş olsa bile, içindeki ABD vizesi iptal edilmediği veya hasar görmediği sürece geçerlidir. Seyahatiniz sırasında eski (vizeli) ve yeni (geçerli) pasaportunuzu yanınızda birlikte taşıyarak seyahat edebilirsiniz.', 5),
  ((SELECT id FROM countries WHERE slug = 'abd'), '10 yıllık ABD vizesi almak, ABD''de 10 yıl boyunca kesintisiz kalabileceğim anlamına mı gelir?', 'Hayır. Vizenin 10 yıllık olması giriş izninizin geçerlilik süresidir. ABD''ye giriş yaptığınızda havalimanındaki Sınır Güvenlik Memuru (CBP) kalabileceğiniz süreyi belirler (genellikle tek girişte en fazla 6 aydır).', 6),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vizesi için mülakata girmem ve parmak izi vermem gerekir mi?', 'Evet. 14-79 yaş arasındaki başvuru sahiplerinin ABD Konsolosluğu''na şahsen giderek mülakata katılması ve parmak izi vermesi zorunludur.', 7),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vize mülakatında Türkçe konuşabilir miyim?', 'Evet. Turistik ve ticari (B1/B2) vize mülakatlarında Konsolosluk yetkilileri Türkçe bilmektedir. Mülakatınızı Türkçe olarak gerçekleştirebilirsiniz. (Öğrenci veya çalışma vizelerinde İngilizce seviyesi ölçülebilir).', 8),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Süresi dolan ABD vizemi mülakata girmeden (posta yoluyla) yenileyebilir miyim?', 'Evet. Daha önce ABD vizesi almış ve vize süresi dolalı belirli bir süreyi geçmemiş kişiler (veya belirli yaş kriterlerindeki başvuru sahipleri) mülakat muafiyeti (Interview Waiver) kapsamında konsolosluğa gitmeden posta yoluyla vizelerini yenileyebilirler.', 9),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Erken randevu (acil randevu) talebi nasıl oluşturulur?', 'Sağlık aciliyetleri, cenaze, acil iş toplantıları veya yaklaşan okul başlangıç tarihleri gibi belgeli acil durumlar için sistem üzerinden kanıtlayıcı evraklar sunularak konsolosluktan öne çekilmiş acil randevu (Expedited Appointment) talep edilebilir.', 10),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Evraklarımı başvuru merkezine götürmem gerekiyor mu, yoksa internetten mi yükleniyor?', 'ABD vize sisteminde ana beyan DS-160 formu üzerinden online yapılır. Destekleyici evraklar internete yüklenmez; randevu günü mülakat esnasında konsolosluk görevlisinin talep etme ihtimaline karşı yanınızda fiziki olarak bulundurulur.', 11),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'Geçerli bir Schengen veya İngiltere vizesinin olması ABD vize şansımı artırır mı?', 'Evet. Daha önce gelişmiş ülkelere yapılmış, kurallara uygun şekilde tamamlanmış seyahat geçmişi (Schengen, İngiltere, Kanada vb.), güvenilir bir seyahat profili çizdiği için ABD vize mülakatında olumlu bir izlenim sağlar.', 12),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vize başvuruları en çok hangi nedenlerle reddedilir?', 'ABD vize retleri büyük oranda 214(b) maddesi (Türkiye''ye yeterli sosyal ve ekonomik bağların gösterilememesi ve göçmenlik potansiyeli şüphesi) kapsamındadır. Ayrıca DS-160 formundaki çelişkili bilgiler ve mülakattaki güvensiz ifadeler de ret nedenlerindendir.', 13),
  ((SELECT id FROM countries WHERE slug = 'abd'), 'ABD vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Evet. ABD vize reddine itiraz mekanizması bulunmamaktadır. Ancak durumunuzda veya finansal/sosyal şartlarınızda önemli bir değişiklik olduğunda yeniden DS-160 formu doldurup yeni bir randevu alarak başvuru yapabilirsiniz.', 14);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya Ziyaretçi Vizesi (Visitor Visa - Subclass 600)', 'Tatil, gezi, aile/arkadaş ziyareti veya kısa süreli iş görüşmeleri amacıyla yapılan seyahatler için verilen vize türüdür.', 0),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya Öğrenci Vizesi (Student Visa - Subclass 500)', 'Avustralya''da dil okulu, lisans, yüksek lisans veya mesleki eğitim alacak kişilerin başvurması gereken vize türüdür.', 1),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya Çalışma ve Tatil Vizesi (Work and Holiday - Subclass 462)', '18-30 yaş arasındaki gençlere Avustralya''da 1 yıla kadar hem tatil yapma hem de çalışma imkânı sunan kotalı vize türüdür.', 2),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya Transit Vizesi (Subclass 771)', 'Avustralya üzerinden başka bir üçüncü ülkeye aktarmalı geçiş yapacak ve havalimanında 8 saatten fazla kalacak kişilerin alması gereken vize türüdür.', 3);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Online Başvurunun Oluşturulması', 'Avustralya vize süreci, ImmiAccount resmi portalı üzerinden online başvuru formunun eksiksiz doldurulmasıyla başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Belgelerin Yüklenmesi ve Harç Ödemesi', 'Seyahat amacınızı, finansal yeterliliğinizi ve Türkiye''ye geri döneceğinizi kanıtlayan tüm belgeler sistem standartlarına uygun olarak dijital ortama yüklenir ve vize harcı ödenir.', 1),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Biyometrik İşlemler', 'Başvuru gönderildikten sonra sistem tarafından Biyometrik Talep Mektubu (Biometrics Requirement Letter) oluşturulur. Bu mektupla yetkili VFS Global merkezinden randevu alınarak parmak izi ve biyometrik fotoğraf teslim edilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Değerlendirme Süreci', 'Değerlendirme doğrudan Avustralya İçişleri Bakanlığı vize memurları tarafından yapılır.', 3),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Sonuç', 'Başvurunuz onaylandığında elektronik vize belgeniz (e-Visa PDF) sistem üzerinden tarafınıza iletilir; pasaportunuza fiziki etiket yapıştırılmaz.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya vizesi pasaporta etiket olarak basılıyor mu?', 'Hayır. Avustralya vizeleri tamamen elektroniktir (e-Visa). Pasaportunuza fiziki bir vize etiketi yapıştırılmaz; onaylandığında vize numaranız dijital olarak pasaport sisteminize tanımlanır ve size onay belgesi (PDF) iletilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya vizesi için konsolosluğa gitmek veya mülakata girmek gerekiyor mu?', 'Hayır, yüz yüze mülakat yapılmaz. Ancak başvuruyu ImmiAccount üzerinden tamamladıktan sonra, parmak izi ve biyometrik fotoğraf vermek için yetkili VFS Global merkezine gitmeniz zorunludur.', 1),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Hiç seyahat geçmişim (Schengen, ABD vb.) yoksa Avustralya vizesi alabilir miyim?', 'Alabilirsiniz ancak zorlaşır. Avustralya Göçmenlik Makamı, Türkiye''den çok uzak bir lokasyona ilk kez gidilmesini "göçmenlik/iltica şüphesi" olarak değerlendirebilir. Seyahat geçmişi olmaması durumunda Türkiye''deki finansal, iş ve ailevi bağların çok güçlü belgelenmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya Turist Vizesi (Subclass 600) ile orada çalışabilir miyim?', 'Hayır. Ziyaretçi vizesi sahiplerinin Avustralya''da herhangi bir işte yasal olarak çalışması kesinlikle yasaktır. Çalışma hakkı yalnızca Öğrenci Vizesi (kısıtlı saatler) ve Work and Holiday (Subclass 462) vizesi sahiplerine tanınır.', 3),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya Öğrenci Vizesi alanların çalışma izni ne kadardır?', 'Öğrenci Vizesi (Subclass 500) sahipleri eğitim dönemleri boyunca 2 haftada toplam 48 saate kadar, resmi okul tatillerinde ise sınırsız çalışma hakkına sahiptir.', 4),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya vizesinde "No Further Stay" (8503 Şartı) ne anlama gelir?', 'Vizenize bu kod eklendiyse, Avustralya''dayken mevcut vizenizi uzatamaz veya başka bir vize türüne (örneğin öğrenci veya çalışma vizesine) içeriden başvuru yapamazsınız. Vize süreniz dolmadan ülkeden çıkış yapmanız gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya vize başvurum reddedilirse itiraz hakkım var mıdır?', 'Avustralya dışından yapılan bireysel turistik başvurularda standart bir itiraz hakkı (AAT temyizi) bulunmaz. Ancak ret gerekçeleri incelenip dosyadaki eksikler giderilerek ImmiAccount üzerinden sıfırdan yeni bir başvuru yapılabilir.', 6),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Sadece Yeni Zelanda vizesi almak için Avustralya transit vizesine başvurmak gerekiyor mu?', 'Evet. Yeni Zelanda''ya giderken Avustralya üzerinden aktarma yapacaksanız ve bekleme süreniz 8 saati aşıyorsa veya havalimanında bagaj alıp yeniden check-in yapmanız gerekiyorsa Avustralya Transit Vizesi (Subclass 771) almanız zorunludur. Transit vize harçsızdır ancak başvuru süreci standart vize gibidir.', 7),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya vizesi kaç yıllık verilir ve ülkede tek seferde en fazla ne kadar kalabilirim?', 'Avustralya turistik vizeleri konsolosluğun takdirine bağlı olarak genellikle 1 yıllık çok girişli (Multiple Entry) olarak düzenlenir. Ancak 1 yıllık vize almanız ülkede 1 yıl aralıksız kalabileceğiniz anlamına gelmez; her girişte tek seferde kalabileceğiniz azami süre genellikle 3 ay (90 gün) ile sınırlandırılır.', 8),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Akraba veya arkadaştan gelen davetiye (Sponsorship) vize onayını kesinleştirir mi?', 'Hayır, tek başına yeterli değildir. Avustralya''daki bir yakınınızın size davetiye göndermesi seyahat amacınızı destekler; ancak vize memuru öncelikle sizin Türkiye''ye geri dönmenizi sağlayacak güçlü ekonomik ve sosyal bağlarınız (düzenli iş, mülk, aile vb.) olup olmadığına bakar.', 9),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya vize başvurusu sonuçlanmadan uçak bileti satın almalı mıyım?', 'Kesinlikle hayır. Avustralya İçişleri Bakanlığı, vizeniz onaylanmadan kesin (ödenmiş) uçak bileti ve otel rezervasyonu yapılmamasını açıkça tavsiye eder. Başvuru aşamasında yalnızca taslak seyahat planı sunmanız yeterlidir.', 10),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Öğrenci veya Ziyaretçi vizesi alırken sağlık taraması (Sağlık Raporu) yaptırmak zorunda mıyım?', 'Her başvuru sahibi için zorunlu değildir. Ancak 6 aydan uzun süreli kalışlarda (Öğrenci vizesi vb.), belirli yaşın üzerindeki başvuru sahiplerinde veya sağlık/bakım sektöründe bulunacak kişilerden Avustralya Konsolosluğu''nun panel doktorlarından alınmış resmi sağlık raporu (Panel Physician Health Assessment) talep edilebilir.', 11),
  ((SELECT id FROM countries WHERE slug = 'avustralya'), 'Avustralya vizesi reddedildikten sonra ödenen başvuru harcı iade edilir mi?', 'Hayır. Vize başvuru harçları başvurunun değerlendirilme süreci için ödenir. Başvurunuz ret ile sonuçlansa dahi Avustralya Hükümeti tarafından ödenen ücretler iade edilmez.', 12);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'bae'), '30 Günlük Tek Girişli Turistik Vize', 'Kısa süreli tatil, iş görüşmesi veya aile ziyareti amacıyla BAE''ye gidecek ve tek bir giriş-çıkış yapacak kişilerin başvurduğu e-vize türüdür.', 0),
  ((SELECT id FROM countries WHERE slug = 'bae'), '30 Günlük Çok Girişli Turistik Vize', '30 günlük süre içinde BAE''ye ve komşu ülkelere (örneğin Umman veya Katar) birden fazla giriş-çıkış yapacak kişilerin tercih ettiği vize türüdür.', 1),
  ((SELECT id FROM countries WHERE slug = 'bae'), '60 Günlük Tek / Çok Girişli Turistik Vize', 'BAE''de daha uzun süre kalmayı, iş aramayı veya uzun süreli tatil yapmayı planlayan kişiler için verilen e-vize türüdür.', 2),
  ((SELECT id FROM countries WHERE slug = 'bae'), '48 ve 96 Saatlik Transit Vize', 'BAE havalimanları (Dubai, Abu Dabi vb.) üzerinden üçüncü bir ülkeye aktarma yapacak ve bekleme süresinde şehre çıkmak isteyen yolcuların alabileceği vize türüdür.', 3);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Dijital Belgelerin Hazırlanması', 'Başvuru için pasaportunuzun resimli sayfasının renkli taranmış hali ve biyometrik fotoğrafınız dijital sisteme yüklenir. Fiziki evrak hazırlığı veya banka dökümü şartı bulunmamaktadır.', 0),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Sisteme Veri Girişi', 'Göçmenlik sistemine (ICP/GDRFA) veri girişi yapıldıktan sonra sistem onay süreci başlar.', 1),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Sonuç ve e-Vize Teslimi', 'Vize onaylandığında, tarafınıza PDF formatında elektronik vize (e-Vize) düzenlenir. Bu belgenin çıktısını alarak seyahat etmeniz yeterlidir; pasaportunuza herhangi bir fiziki etiket yapıştırılmaz.', 2);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Dubai vizesi almak Abu Dabi veya Şarjah seyahatleri için de geçerli midir?', 'Evet. Alınan e-vize Birleşik Arap Emirlikleri''nin tüm emirliklerinde (Dubai, Abu Dabi, Şarjah, Ajman, Fuceyre, Resül-Hayme, Ümmül-Kayveyn) geçerlidir. Her emirlik için ayrı vize alınmaz.', 0),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Dubai e-Vizesi kaç günde çıkar?', 'Başvurular standart olarak 24 ila 48 saat içerisinde sonuçlanmaktadır. Ancak BAE''de cuma öğleden sonra, cumartesi ve pazar günlerinin resmi tatil/hafta sonu olduğu ve sistem incelemelerinin bu günlerde yavaşlayabileceği göz önünde bulundurulmalıdır.', 1),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Dubai vizesi onaylandıktan sonra ne kadar süre içinde kullanılmalıdır?', 'Onaylanan e-vizenin geçerlilik süresi düzenlendiği tarihten itibaren 60 gündür. Vizeniz çıktıktan sonra 60 gün içinde BAE''ye giriş yapmanız gerekir. Giriş yaptıktan sonra vize tipinize göre (30 veya 60 gün) kalış süreniz başlar.', 2),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'BAE vize başvurusunda parmak izi verilmesi veya konsolosluğa gidilmesi gerekiyor mu?', 'Hayır. Başvuru aşamasında parmak izi verilmez ve konsolosluğa gidilmez. Biyometrik göz/yüz taraması yalnızca BAE havalimanına vardığınızda pasaport kontrol noktasında yapılır.', 3),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Yeşil (Hususi) Pasaport sahiplerinin Dubai''ye giderken vize alması gerekir mi?', 'Hayır. Hususi (yeşil), Hizmet (gri) ve Diplomatik (siyah) pasaport sahibi T.C. vatandaşları 180 gün içinde 90 güne kadar BAE seyahatlerinde vizeden muaftır.', 4),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'BAE e-Vizesi ile BAE''de yasal olarak çalışabilir miyim?', 'Hayır. Turistik veya ticari e-vize ile BAE''de çalışmak kesinlikle yasaktır. BAE''de çalışabilmek için BAE merkezli bir şirketin size resmi Çalışma İzni (Work Permit) ve Oturum Vizesi (Residency Visa) çıkarması şarttır.', 5),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Tek başıma seyahat edecek 18-21 yaş arası gençlerin veya kadınların BAE vizesi alması zor mudur?', 'BAE Göçmenlik Dairesi 18-21 yaş altı bireylerin tek başına seyahatlerinde sistem üzerinden ek güvenlik kontrolleri veya birinci derece akraba güvencesi talep edebilir. Bu yaş grubundaki kişilerin başvurularının dikkatle planlanması gerekir.', 6),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Dubai havalimanında aktarmam var, şehre çıkmak için vize almalı mıyım?', 'Havalimanının transit alanından çıkmayıp yalnızca uçak değiştirecekseniz vizeye ihtiyacınız yoktur. Ancak havalimanından çıkıp şehre gezmeye gitmek veya bagajınızı alıp başka bir havayoluyla yeniden check-in yapmak istiyorsanız Transit Vize veya 30 Günlük Turistik Vize almanız gerekir.', 7),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'BAE vizesi alırken banka hesap dökümü veya maaş bordrosu sunmak zorunda mıyım?', 'Hayır. Standart BAE e-vize başvurularında konsolosluk tarzı banka dökümleri, tapu, çalışma belgeleri veya maaş bordroları talep edilmez. Başvuru tamamen pasaport ve fotoğraf ile yapılır.', 8),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'BAE vize ihlali (Overstay) yapılırsa ne olur?', 'Vizenizin izin verdiği kalış süresini (30 veya 60 gün) aşmanız durumunda BAE Göçmenlik Dairesi kaldığınız her fazla gün için sistem üzerinden ciddi para cezaları uygular. Ayrıca ceza ödenmeden ülkeden çıkışa izin verilmez ve sonraki başvurularınız için giriş yasağı koyulabilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'BAE vize başvurum reddedilirse ödediğim harç iade edilir mi?', 'Hayır. BAE Göçmenlik Dairesi (ICP/GDRFA) başvurunun incelenmesi aşamasında harcı tahsil eder. Başvurunun reddedilmesi durumunda ödenen vize ücretleri iade edilmez.', 10),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Sadece uçak bileti ve otel rezervasyonu ile BAE vizesi alınabilir mi?', 'BAE e-Vize başvurusunda otel veya uçak bileti sunmak kural olarak zorunlu değildir; sadece pasaport ve fotoğraf yeterlidir. Ancak sınır kontrolü sırasında BAE polisinin dönüş biletinizi ve konaklayacağınız yeri sorma hakkı saklıdır.', 11),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Ülkeye giriş yaptıktan sonra vize süremi BAE''den çıkmadan uzatabilir miyim?', 'Evet. BAE Göçmenlik Dairesi''nin sunduğu sistem sayesinde, 30 veya 60 günlük turistik vizenizi BAE dışına çıkış yapmadan (Inside Country Visa Change) ek harç ödeyerek uzatabilirsiniz.', 12),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Ad-soyad benzerliğinden dolayı vize onayının takılması (Blacklist / Security Check) nedir?', 'BAE göçmenlik sistemi isim bazlı güvenlik taraması yapar. Adınız veya soyadınız BAE güvenlik listesindeki (kara liste) biriyle eşleşirse başvurunuz "Security Check"e düşer. Bu durumda ek kimlik doğrulamaları veya pasaport detayları talep edilebilir ve süreç birkaç gün uzayabilir.', 13),
  ((SELECT id FROM countries WHERE slug = 'bae'), 'Eski pasaportumdaki vize ile yeni pasaportumla BAE''ye giriş yapabilir miyim?', 'Hayır. BAE e-vizeleri doğrudan başvuru yaptığınız pasaport numarasına dijital olarak tanımlanır. Pasaportunuzu yenilediyseniz eski pasaporttaki vizeyle seyahat edemezsiniz; yeni pasaport numaranızla sıfırdan e-vize almanız gerekir.', 14);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin Turistik Vizesi (L Vizesi)', 'Çin''e turistik gezi, kültürel seyahat veya bireysel ziyaret amacıyla gidecek kişilerin başvurabileceği vize türüdür.', 0),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin Ticari Vizesi (M Vizesi)', 'Çin''de iş görüşmesi, fuar, ticari toplantı veya diğer ticari faaliyetlere katılacak kişilerin başvurabileceği vize türüdür.', 1),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin Çalışma Vizesi (Z Vizesi)', 'Çin''de yasal olarak çalışacak kişilerin başvurması gereken vize türüdür.', 2),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin Öğrenci Vizesi (X1 / X2)', 'Çin''de eğitim alacak öğrencilerin başvurabileceği vize türüdür. Eğitim süresine göre X1 veya X2 vizesi uygulanır.', 3),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin Aile Ziyareti Vizesi (Q1 / Q2)', 'Çin vatandaşı veya Çin''de daimi ikamet eden aile üyelerini ziyaret edecek kişilerin başvurabileceği vize türüdür.', 4);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Vize Türünün Belirlenmesi', 'Çin vize süreci, seyahat amacınıza uygun vize türünün belirlenmesi ve gerekli belgelerin hazırlanmasıyla başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Online Form ve Onay', 'COAVS sistemi üzerinden online başvuru formu eksiksiz doldurulur, gerekli bilgiler ve fotoğraf sisteme yüklenerek başvuru formunun onay süreci tamamlanır.', 1),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Randevu ve Evrak Teslimi', 'Form onaylandıktan sonra yetkili Çin Vize Başvuru Merkezi üzerinden randevu alınır. Randevu tarihinde başvuru için hazırlanan fiziki evraklar teslim edilir ve gerekli biyometrik işlemler gerçekleştirilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Değerlendirme Süreci', 'Başvuru dosyası, Çin''in ilgili konsolosluk makamları tarafından değerlendirilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Sonuç ve Pasaport Teslimi', 'Başvurunun olumlu sonuçlanması halinde vize pasaportunuza işlenir ve pasaportunuz başvuru merkezi üzerinden teslim alınır.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin vize başvurusunu ne kadar önce yapmalıyım?', 'Çin vize başvurularında işlem süreleri dönemsel yoğunluğa ve başvuru türüne göre değişiklik gösterebilir. Seyahat planınızda aksama yaşamamak adına başvurunuzu planlanan seyahat tarihinden mümkün olduğunca önce başlatmanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin vizesi kaç günde sonuçlanır?', 'Başvuruların sonuçlanma süresi başvuru türüne, konsolosluk yoğunluğuna ve seçilen işlem türüne göre değişebilir. Standart ve ekspres işlem seçenekleri bulunabilmektedir.', 1),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin vizesi için parmak izi vermem gerekir mi?', 'Çin vize başvurularında biyometrik veri uygulaması başvuru sahibinin yaşına, vize türüne ve güncel muafiyet koşullarına göre değişiklik gösterebilir. Başvuru öncesinde güncel biyometrik uygulamanın kontrol edilmesi gerekir.', 2),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin vizesi için mülakata girmem gerekir mi?', 'Standart başvurularda her başvuru sahibi için yüz yüze mülakat uygulanmaz. Ancak konsolosluk gerekli gördüğü durumlarda başvuru sahibini görüşmeye çağırabilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Çin vizesi için herkes açısından geçerli sabit bir banka bakiyesi bulunmamaktadır. Finansal belgelerin, seyahat masraflarınızı karşılayabilecek durumda olduğunuzu gösterecek şekilde hazırlanması önemlidir.', 4),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin vizesi için davetiye gerekli midir?', 'Davetiye, başvurulan vize türüne göre değişiklik gösterir. Özellikle ticari (M) vize başvurularında Çin''deki davet eden kurum veya şirketten alınan davet mektubu başvuru dosyasının önemli belgelerinden biridir.', 5),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin''e turistik seyahat için hangi vizeye başvurmalıyım?', 'Turistik amaçlı seyahatler için L Vizesi başvurusu yapılır. Seyahatinizin amacı ve planlanan kalış süresine göre uygun vize türü ve giriş sayısı belirlenir.', 6),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin''e fuar veya iş görüşmesi için hangi vizeyle gidebilirim?', 'Fuar, iş görüşmesi, ticari toplantı ve benzeri ticari faaliyetler için M Vizesi başvurusu yapılır. Başvuru sırasında seyahat amacını destekleyen ticari belgelerin ve gerekli davetiyenin sunulması gerekebilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Hong Kong veya Makao''ya gidip Çin''e tekrar giriş yapacaksam vizem nasıl olmalı?', 'Çin ana karasına tekrar giriş yapmayı planlıyorsanız vizenizin giriş sayısına dikkat etmeniz gerekir. Tek girişli bir Çin vizesiyle Çin''den çıktıktan sonra aynı vizeyle tekrar giriş yapılamaz. Seyahat planınıza göre çift veya çok girişli vize gerekebilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Eski pasaportumda geçerli Çin vizem varsa yeni pasaportumla seyahat edebilir miyim?', 'Bu durum vizenin ve pasaportların durumuna göre değişebilir. Seyahat öncesinde eski pasaporttaki vizenin yeni pasaportla birlikte kullanılıp kullanılamayacağı Çin konsolosluk makamlarından teyit edilmelidir.', 9),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin vizesi reddedilirse tekrar başvuru yapabilir miyim?', 'Evet. Ret sonrasında yeniden başvuru yapılabilir. Ancak yeni başvurudan önce önceki başvurunun ret gerekçelerinin değerlendirilmesi ve gerekli eksikliklerin giderilmesi önemlidir.', 10),
  ((SELECT id FROM countries WHERE slug = 'cin'), 'Çin vizesi ile ülkede izin verilen süreden fazla kalabilir miyim?', 'Hayır. Çin vizesinde belirtilen izin verilen kalış süresinin aşılmaması gerekir. Seyahat planınızın vizenizde tanınan kalış süresiyle uyumlu olması önemlidir.', 11);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla İngiltere''ye gitmek isteyen kişilerin başvurabileceği Standart Ziyaretçi Vizesidir (Standard Visitor Visa).', 0),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı, konferans veya ticari etkinliklere katılım amacıyla yapılan seyahatler için başvurulan Standart Ziyaretçi Vizesidir.', 1),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere Aile ve Arkadaş Ziyareti Vizesi', 'İngiltere''de yaşayan aile bireylerini, akrabaları veya arkadaşları ziyaret etmek isteyen kişilerin başvurabileceği Standart Ziyaretçi Vizesidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere Aile Birleşimi ve Yerleşim Vizesi', 'İngiltere''de yasal olarak yaşayan veya İngiliz vatandaşı olan eş/aile bireylerinin yanına uzun süreli yerleşim amacıyla başvurulan yerleşim (Family / Spouse Visa) vizesidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere Öğrenci Vizesi (Student / Short-term Student)', 'İngiltere''de üniversite eğitimi, dil kursu veya diğer eğitim programlarına katılacak kişilerin başvurabileceği öğrenci vizesi türüdür.', 4),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere Çalışma Vizesi (Vasıflı Çalışan - Skilled Worker)', 'İngiltere''de bir işveren tarafından sponsorluk lisansı ile istihdam edilmek isteyen kişilerin başvurabileceği puan tabanlı çalışma vizesidir.', 5),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere Transit Vizesi', 'İngiltere üzerinden başka bir ülkeye aktarmalı geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği vize türüdür.', 6),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere Tıbbi Tedavi Vizesi', 'İngiltere''deki özel veya resmi sağlık kuruluşlarında tıbbi tedavi görmek amacıyla başvurulan özel ziyaretçi vizesidir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'Vize Türünün Belirlenmesi', 'İngiltere vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'Online Form ve Belge Yükleme', 'GOV.UK portalı üzerinden resmi başvuru formu İngilizce olarak doldurulur, vize harcı ödenir ve seyahat planınızı destekleyen belgeler dijital ortama (PDF) yüklenir.', 1),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'Biyometrik İşlemler', 'Randevu tarihinde VFS Global başvuru merkezinde biyometrik işlemler (fotoğraf ve parmak izi) gerçekleştirilir. İngiltere vize başvurularında daha önce vize alınmış olsa dahi her başvuruda yeniden parmak izi verilmesi zorunludur.', 2),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra İngiltere İçişleri Bakanlığı (Home Office) tarafından değerlendirme süreci başlar. Konsolosluk gerekli gördüğü durumlarda ek belge talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vize başvurusunu ne kadar önce yapmalıyım?', 'İngiltere vize başvuruları, planlanan seyahat tarihinden en erken 3 ay önce yapılabilir. Randevu yoğunlukları ve değerlendirme süresi göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 6-8 hafta önce tamamlamanız tavsiye edilir. Özellikle yaz sezonunda ve resmi tatil dönemlerinde randevu bulmak zorlaşabileceğinden başvurunuzu mümkün olduğunca erken planlamanız önerilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vizesi kaç günde sonuçlanır?', 'Standart İngiltere vize başvuruları, başvuru merkezindeki biyometrik randevu tarihinden itibaren ortalama 15 iş günü (3 hafta) içerisinde sonuçlandırılır. Ek belge talep edilmesi veya detaylı incelemeye alınması durumunda bu süre uzayabilir. Ayrıca ek harç ödenerek sunulan ekspres vize (Priority veya Super Priority) hizmetleriyle süreci kısaltmak mümkündür.', 1),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vize ücreti ne kadardır?', 'Vize ücretleri; başvurulan vize türüne, talep edilen vize süresine (6 ay, 2 yıl, 5 yıl, 10 yıl) ve tercih edilecek ek hizmetlere (ekspres vize, VIP hizmetler vb.) göre değişiklik göstermektedir. Güncel başvuru harçları ve hizmet bedelleri hakkında detaylı bilgi almak için ekibimizle iletişime geçebilirsiniz.', 2),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'İngiltere Konsolosluğu tarafından belirlenmiş sabit ve resmi bir minimum banka bakiyesi bulunmamaktadır. Hesabınızda, seyahat süreniz boyunca ulaşım, konaklama ve kişisel harcamalarınızı karşılamaya yetecek tutarın bulunması beklenir. En kritik husus; hesabınızdaki paranın kaynağının düzenli geliriniz ve sunduğunuz evraklarla %100 uyumlu, şeffaf ve açıklanabilir olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'İngiltere için pasaportunuzun, seyahatiniz boyunca ve İngiltere''de kalmayı planladığınız süre boyunca geçerli olması yeterlidir. Schengen vizelerindeki gibi dönüş sonrası ek 3 ay şartı aranmaz. Ancak pasaportunuzda en az 1 adet boş vize sayfası bulunması zorunludur.', 4),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vizesi için parmak izi vermem gerekir mi?', 'Evet, İngiltere vize başvurularında biyometrik veri (parmak izi ve dijital fotoğraf) verilmesi zorunludur. Daha önce Schengen veya İngiltere vizesi için parmak izi vermiş olsanız bile, her yeni İngiltere başvurusunda VFS Global merkezine şahsen giderek biyometrik işlemlerinizi tekrarlamanız gerekir.', 5),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'Evraklarımı başvuru merkezine götürmem gerekiyor mu, yoksa internetten mi yükleniyor?', 'İngiltere vize sisteminde tüm destekleyici belgeler randevu gününden önce sisteme dijital (PDF) olarak yüklenir. Randevu günü başvuru merkezine fiziki dosya taşımak yerine yalnızca pasaportunuz ve randevu onay belgeniz ile gitmeniz yeterlidir.', 6),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'Geçerli bir Schengen vize geçmişimin olması İngiltere vize şansımı artırır mı?', 'Evet. Daha önce Schengen ülkelerine, ABD''ye veya Kanada''ya yapılmış ve kurallara uygun şekilde tamamlanmış seyahatler, İngiltere başvurunuzda "güvenilir seyahat geçmişi" olarak olumlu değerlendirilir ve dosyanızı güçlendirir.', 7),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'Birleşik Krallık vizesi ile İskoçya, Galler veya Kuzey İrlanda''ya seyahat edebilir miyim?', 'Evet. Alacağınız Birleşik Krallık vizesi ile İngiltere, İskoçya, Galler ve Kuzey İrlanda''nın tamamına ek bir vizeye ihtiyaç duymadan seyahat edebilirsiniz.', 8),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vizesi ile Schengen ülkelerine seyahat edebilir miyim?', 'Hayır, İngiltere Schengen Alanı''na veya Avrupa Birliği''ne dâhil değildir. İngiltere vizesi ile Schengen ülkelerine (Almanya, Fransa, İtalya vb.) giriş yapamazsınız. Bu ülkelere seyahat edebilmek için ayrıca Schengen vizesi almanız gerekmektedir.', 9),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vizesi ne kadar süreyle verilir?', 'İngiltere turistik/ziyaretçi vizeleri standart olarak en az 6 aylık ve çok girişli (Multiple Entry) olarak verilir. Düzenli seyahat geçmişi bulunan kişilere konsolosluk değerlendirmesine bağlı olarak 2 yıllık, 5 yıllık veya 10 yıllık uzun süreli vizeler de verilebilmektedir.', 10),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vize başvuruları en çok hangi nedenlerle reddedilir?', 'İngiltere vize başvurularındaki en yaygın ret nedenleri; banka hesabındaki açıklanamayan düzensiz/yüksek para girişleri, kaynağı belgelenmeyen finansal birikimler, başvuru sahibinin Türkiye''deki sosyo-ekonomik bağlarının yetersiz görülmesi ve seyahat amacının inandırıcı bulunmamasıdır.', 11),
  ((SELECT id FROM countries WHERE slug = 'ingiltere'), 'İngiltere vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'İngiltere vize başvurunuzun reddedilmesi yeniden başvuru yapmanıza engel değildir. Ancak ret mektubundaki gerekçeler detaylıca analiz edilip, eksiklikler tam olarak giderilmeden yapılan tekrar başvurular yeniden ret ile sonuçlanabilir. Bu nedenle yeni başvurunun ret gerekçelerine yanıt veren güçlü bir dosya ile yapılması kritik önem taşır.', 12);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda Turistik Vizesi', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla İrlanda''ya gitmek isteyen kişilerin başvurabileceği Kısa Süreli Ziyaretçi Vizesidir (Short Stay ''C'' Tourist Visa).', 0),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda Ticari Vizesi', 'İş görüşmesi, şirket ziyareti, toplantı veya konferans katılımı amacıyla yapılan seyahatler için başvurulan Kısa Süreli Ticari Vizedir (Short Stay ''C'' Business Visa).', 1),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda Aile ve Arkadaş Ziyareti Vizesi', 'İrlanda''da yaşayan aile bireylerini veya arkadaşları ziyaret etmek isteyen kişilerin başvurabileceği ziyaret vizesidir (Visit Friend / Family).', 2),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda Öğrenci Vizesi', 'İrlanda''da dil eğitimi (özellikle İngilizce dil okulları) veya üniversite/yükseköğrenim programlarına katılacak kişilerin süresine göre (''C'' veya ''D'' tipi) başvuracağı eğitim vizesidir.', 3),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda Aile Birleşimi Vizesi', 'İrlanda''da yasal olarak yaşayan veya İrlanda vatandaşı olan kişilerin aile üyelerinin yanına yerleşmesi için başvurulan uzun süreli (''D'' tipi Join Family) vizedir.', 4),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda Çalışma Vizesi', 'İrlanda''da bir işverenden kabul almış ve yetkili makamlardan çalışma izni (Employment Permit) alınmış kişilerin başvurabileceği uzun süreli (''D'' tipi) vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda Transit Vizesi', 'İrlanda üzerinden başka bir ülkeye aktarmalı geçiş yapacak ve transit vizeye tabi olan yolcuların başvurabileceği vize türüdür.', 6);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'Vize Türünün Belirlenmesi', 'İrlanda vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'AVATS Formu ve Randevu', 'AVATS portalı üzerinden resmi başvuru formu İngilizce olarak doldurulur. Ardından sistemin sunduğu özet belgesi ve dilekçe hazırlanarak VFS Global merkezinden randevu alınır.', 1),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'Evrak Teslimi', 'Randevu tarihinde başvuru merkezinde fiziki evrak dosyası ve pasaport teslim edilir. İrlanda konsolosluk prosedürleri gereği başvurularda belgelerin asılları ve Türkçe belgelerin İngilizce tercümeleri dosyaya eklenir.', 2),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'Değerlendirme Süreci', 'Başvuru dosyanız teslim edildikten sonra Ankara İrlanda Büyükelçiliği / İrlanda Göçmenlik Makamı tarafından değerlendirme süreci başlar. Konsolosluk gerekli gördüğü durumlarda ek belge veya mülakat talep edebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'Sonuç ve Pasaport Teslimi', 'Değerlendirme tamamlandığında pasaportunuz başvuru merkezi aracılığıyla teslim edilir. Vizenizin onaylanması halinde pasaportunuz içerisinde vize etiketiyle birlikte teslim edilir; başvurunun olumsuz sonuçlanması halinde ise ret gerekçesini içeren karar formu ile birlikte pasaportunuz tarafınıza iade edilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vize başvurusunu ne kadar önce yapmalıyım?', 'İrlanda vize başvuruları, planlanan seyahat tarihinden en erken 3 ay önce yapılabilir. Konsolosluk inceleme süreleri ve randevu yoğunlukları göz önünde bulundurulduğunda, başvurunuzu seyahatinizden en az 6-8 hafta önce tamamlamanız önemle tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vizesi kaç günde sonuçlanır?', 'İrlanda vize başvurularının değerlendirme süresi vize türüne ve dönemsel yoğunluğa göre değişmekle birlikte, standart turistik başvurular için ortalama 15-20 iş günü (3-4 hafta) sürmektedir. Uzun süreli veya çalışma/eğitim vizelerinde bu süre uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vize ücreti ne kadardır?', 'Vize ücretleri; başvurulan vize türüne (Tek girişli ''C'', Çok girişli ''C'' veya Uzun dönem ''D'' tipi) ve tercih edilecek ek hizmetlere göre değişiklik göstermektedir. Güncel başvuru harçları ve hizmet bedelleri hakkında detaylı bilgi almak için ekibimizle iletişime geçebilirsiniz.', 2),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'İrlanda Konsolosluğu sabit bir tutar ilan etmemekle birlikte, son 6 aylık banka dökümünüzde seyahat masraflarınızı karşılayacak miktarın bulunmasını ister. En kritik kural; hesaptaki paranın aniden yatırılmamış olması, kaynağının şeffaf, düzenli gelirinize dayalı ve belgelenebilir olmasıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'İrlanda başvurularında pasaportunuzun, planlanan seyahat bitiş (dönüş) tarihinizden itibaren en az 6 ay daha geçerli olması ve en az 2 adet boş vize sayfasının bulunması zorunludur.', 4),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vizesi için parmak izi vermem gerekir mi?', 'İrlanda vize sisteminde şu an için standart biyometrik parmak izi verisi alınmamaktadır; ancak evrak teslimi ve pasaport kontrolü için başvuru sahibinin veya yetkili temsilcisinin VFS Global merkezine şahsen başvurması gerekmektedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'Evraklarımı başvuru merkezine götürmem gerekiyor mu, yoksa internetten mi yükleniyor?', 'İrlanda başvuru sürecinde AVATS formu online doldurulduktan sonra, hazırlanan tüm evrakların ve pasaportun asıllarının/fotokopilerinin randevu gününde fiziki olarak VFS Global başvuru merkezine teslim edilmesi gerekmektedir.', 6),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'Geçerli bir Schengen veya İngiltere vize geçmişimin olması İrlanda vize şansımı artırır mı?', 'Evet. Daha önce Schengen alanına, İngiltere''ye, ABD''ye veya Kanada''ya yapılmış ve kurallara uygun tamamlanmış seyahatler, seyahat geçmişinizi kanıtladığı için İrlanda vize dosyanızı oldukça güçlü kılar.', 7),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'Birleşik Krallık (İngiltere) vizesi veya Schengen vizesi ile İrlanda''da seyahat edebilir miyim?', 'İrlanda Schengen Alanı''na dâhil değildir, bu nedenle Schengen vizesi ile İrlanda''ya giriş yapılamaz. Ancak İngiltere ile İrlanda arasındaki özel muafiyet programı (BIVS - British-Irish Visa Scheme) kapsamında, belirli şartları taşıyan ve üzerinde ''BIVS'' ibaresi bulunan İngiltere vizeleriyle (önce İngiltere''ye giriş yapmak kaydıyla) İrlanda''ya geçiş mümkündür. Standart vizelerde ise ayrı İrlanda vizesi alınmalıdır.', 8),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vizesi ne kadar süreyle verilir?', 'İlk kez başvuran kişilere genellikle seyahat tarihlerini kapsayan tek girişli (Single Entry) vize verilir. Düzenli seyahat geçmişi ve haklı gerekçeleri olan başvuru sahiplerine konsolosluk takdirine bağlı olarak çok girişli (Multiple Entry) vizeler de tanımlanabilmektedir.', 9),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vize başvuruları en çok hangi nedenlerle reddedilir?', 'En sık karşılaşılan ret nedenleri; banka hesabındaki paranın kaynağının belgelenememesi/son dakika toplu para yatırılması, Türkiye''ye geri dönüleceğine dair bağların inandırıcı bulunmaması, seyahat amacının tam açıklanamaması ve eksik/hatalı belge sunulmasıdır.', 10),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'İrlanda vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Evet. Ret kararı sonrasında eksiklikler giderilerek yeniden başvuru yapılabileceği gibi, kararın tebliğ edilmesinden itibaren belirtilen süre içerisinde (genellikle 2 ay) ret kararına itiraz etme (Appeal) hakkınız da bulunmaktadır.', 11),
  ((SELECT id FROM countries WHERE slug = 'irlanda'), 'Kuzey İrlanda''ya (Belfast) seyahat etmek için İrlanda vizesi yeterli midir?', 'Hayır. Kuzey İrlanda (Belfast), Birleşik Krallık (İngiltere) toprağıdır. İrlanda Cumhuriyeti (Dublin) vizesi ile Kuzey İrlanda''ya geçiş yapılamaz. Kuzey İrlanda seyahati için İngiltere vizesi alınması zorunludur.', 12);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada Turistik Vizesi (Visitor Visa / TRV)', 'Tatil, gezi, kültürel etkinlikler ve bireysel seyahatler amacıyla Kanada''ya gitmek isteyen kişilerin başvurabileceği Geçici İkamet Vizesidir.', 0),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada Ticari Vizesi (Business Visitor)', 'İş görüşmesi, konferans, fuar katılımı veya ticari toplantılar amacıyla yapılan seyahatler için başvurulan ziyaretçi vizesidir.', 1),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada Aile ve Arkadaş Ziyareti Vizesi', 'Kanada''da yasal olarak oturan aile bireylerini veya arkadaşları ziyaret etmek amacıyla yapılan başvurulardır.', 2),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada Öğrenci Vizesi ve Öğrenim İzni (Study Permit)', 'Kanada''da 6 aydan kısa süreli dil okulları için standart ziyaretçi vizesi; 6 aydan uzun süren dil okulu, kolej veya üniversite eğitimleri için ise Öğrenim İzni (Study Permit) alınmalıdır.', 3),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada Çalışma İzni (Work Permit)', 'Kanada''daki bir işverenden onaylı iş teklifi (LMIA) alan veya açık çalışma izni kategorilerine uyan kişilerin başvurabileceği izin türüdür.', 4),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada Süper Vize (Super Visa)', 'Kanada vatandaşlarının veya daimi ikamet edenlerin (Permanent Resident) ebeveynleri ve büyükanne/büyükbabaları için verilen, 10 yıla kadar geçerli ve tek girişte 5 yıla kadar kalış imkânı sunan özel vize türüdür.', 5),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada Transit Vizesi', 'Kanada havalimanları üzerinden başka bir üçüncü ülkeye aktarmalı geçiş yapacak yolcuların alması gereken vize türüdür.', 6);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Vize Türünün Belirlenmesi', 'Kanada vize başvurusu, seyahat amacınıza uygun vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'IRCC Formları ve Belge Yükleme', 'IRCC portalı üzerinden resmi başvuru formları eksiksiz doldurulur, seyahat planınızı ve Türkiye''ye geri döneceğinizi kanıtlayan tüm belgeler dijital ortama (PDF) yüklenir ve vize harcı ödenir.', 1),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Biyometrik İşlemler', 'Başvuru yüklendikten sonra IRCC tarafından Biyometrik Talep Mektubu (Biometric Instruction Letter) düzenlenir. Bu mektupla VFS Global merkezinden randevu alınarak parmak izi ve fotoğraf işlemleri tamamlanır.', 2),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Değerlendirme Süreci', 'Değerlendirme süreci doğrudan Kanada Göçmenlik Makamı (IRCC) tarafından yürütülür.', 3),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Sonuç ve Pasaport Teslimi', 'Başvurunun onaylanması durumunda pasaport talep mektubu (Passport Submission Letter) iletilir ve pasaport basım için VFS Global aracılığıyla konsolosluğa gönderilir.', 4);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vize başvurusunu ne kadar önce yapmalıyım?', 'Kanada vize inceleme süreleri dönemsel olarak ve dosya yoğunluğuna göre değişebilmektedir. Seyahat planınızda aksama yaşamamak adına başvurunuzu planlanan seyahat tarihinizden en az 2-3 ay önce başlatmanız tavsiye edilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vizesi kaç günde sonuçlanır?', 'Biyometrik verilerin verilmesinin ardından standart ziyaretçi vizesi başvuruları ortalama 4 ila 8 hafta içerisinde sonuçlanmaktadır. Yoğun dönemlerde veya ek inceleme gerektiren durumlarda bu süre uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vize ücreti ne kadardır?', 'Vize ücretleri; başvurulan vize türüne (Ziyaretçi vizesi, Öğrenim/Çalışma izni), biyometrik veri ücretine ve tercih edilecek ek hizmetlere göre değişiklik göstermektedir. Güncel başvuru harçları ve hizmet bedellerimiz hakkında detaylı bilgi almak için ekibimizle iletişime geçebilirsiniz.', 2),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Kanada Konsolosluğu sabit bir tutar ilan etmez. Ancak hesabınızda uçak bileti, konaklama ve günlük harcamalarınızı rahatlıkla karşılayacak tutarda bakiye bulunmalıdır. Paranın kaynağının düzenli gelirinize dayanması ve hesaba son dakika kaynağı belirsiz toplu para yatırılmamış olması en kritik kuraldır.', 3),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun planlanan seyahat süresini kapsayacak geçerlilikte olması yeterlidir. Ancak Kanada vizeleri genellikle pasaport süresinin bitim tarihine kadar verildiği için, uzun süreli vize alabilmek adına pasaport sürenizin olabildiğince uzun (örneğin 10 yıllık) olması büyük avantaj sağlar.', 4),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vizesi ne kadar süreyle verilir?', 'Kanada vizeleri kural olarak çok girişli (Multiple Entry) ve başvuru sahibinin mevcut pasaportunun geçerlilik süresinin son gününe kadar (en fazla 10 yıla kadar) verilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vizesi için parmak izi vermem gerekir mi?', 'Evet. Kanada vize başvurularında biyometrik veri (parmak izi ve fotoğraf) verilmesi zorunludur. Verilen biyometrik veriler 10 yıl boyunca geçerlidir; son 10 yıl içinde Kanada için parmak izi verdiyseniz yeni başvuruda tekrar vermeniz gerekmez.', 6),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Evraklarımı başvuru merkezine götürmem gerekiyor mu, yoksa internetten mi yükleniyor?', 'Kanada vize başvurusunda tüm destekleyici belgeler internet üzerinden (IRCC Portal) dijital olarak yüklenir. Başvuru merkezine (VFS Global) yalnızca biyometrik işlem (parmak izi) vermek ve vize onaylandıktan sonra pasaportunuzu teslime etmek için gidilir.', 7),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vize mülakatı yapılıyor mu?', 'Hayır, Kanada vize başvurularında standart olarak yüz yüze mülakat yapılmaz. Tüm değerlendirme sisteme yüklenen dijital belgeler ve niyet mektubu üzerinden gerçekleştirilir. Konsolosluk çok istisnai durumlarda mülakat talep edebilir.', 8),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Geçerli bir ABD vizesinin olması Kanada vize başvurusunu etkiler mi?', 'Evet. Geçerli bir ABD vizesine sahip olmak veya son 10 yıl içinde Kanada/ABD vizesi almış olmak başvuru sürecinizi kolaylaştırır (CAN+ Programı kapsamına girebilirsiniz) ve finansal evrak yükünüzü hafifleterek onay şansınızı artırabilir.', 9),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Akrabalarımdan veya arkadaşlarımdan davetiye gelmesi vize almamı garantiler mi?', 'Hayır. Davetiye tek başına vize garantisi sağlamaz. Önemli olan davet eden kişinin Kanada''daki yasal statüsü ile başvuru sahibinin Türkiye''ye olan bağlarını ve seyahat masraflarını nasıl karşılayacağını eksiksiz belgelemesidir.', 10),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vize başvuruları en çok hangi nedenlerle reddedilir?', 'En yaygın ret gerekçeleri; başvuru sahibinin Türkiye''deki finansal ve ailevi bağlarının yetersiz görülmesi (ülkesine geri döneceğine ikna olunmaması), seyahat amacının inandırıcı bulunmaması, banka hesabındaki paranın kaynağının belgelenememesi ve eksik/çelişkili belge sunulmasıdır.', 11),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Evet. Ret gerekçelerini ayrıntılı olarak gösteren GCMS Notları (Global Case Management System) talep edilip ret nedeni tam olarak analiz edildikten sonra, eksiklikler giderilerek yeniden başvuru yapılabilir.', 12),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Kanada vizesi alıp Amerika''ya, ya da ABD vizesiyle Kanada''ya kara yoluyla geçebilir miyim?', 'Kanada vizesi ile ABD''ye giriş yapılamaz, iki ülke bağımsız vize rejimlerine sahiptir. Aynı şekilde yalnızca ABD vizeniz olması Kanada''ya geçiş hakkı tanımaz. İki ülke arasında (kara veya hava yoluyla) geçiş yapabilmek için her iki ülkenin de geçerli vizesine sahip olmanız gerekir.', 13),
  ((SELECT id FROM countries WHERE slug = 'kanada'), 'Sadece dil okuluna gitmek için vize alıp orada çalışabilir miyim?', 'Hayır. Kanada''da dil eğitimi (ESL/FSL) alan öğrencilerin haftalık yarı zamanlı çalışma izni (Work Permit) hakkı yoktur. Çalışma izni hakkı yalnızca devlet kolejleri veya üniversitelerde tam zamanlı akademik eğitim alan öğrencilere tanınır.', 14);
INSERT INTO country_visa_types (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Turistik Vize (C Tipi)', 'Gezi, tatil ve bireysel seyahat amacıyla yapılan kısa süreli başvurular için düzenlenen C Tipi Schengen vizesidir. Seyahat süresi, vizenin geçerlilik tarihleri ve izin verilen kalış süresi başvurunun değerlendirilmesine göre belirlenir.', 0),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Ticari Vize (C Tipi)', 'İş görüşmeleri, şirket ziyaretleri, toplantılar, fuarlar ve ticari organizasyonlara katılım amacıyla yapılan kısa süreli seyahatler için düzenlenen C Tipi Schengen vizesidir.', 1),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Aile Ziyareti Vizesi (C Tipi)', 'Schengen Bölgesi''nde yaşayan aile bireylerini veya yakınlarını ziyaret etmek amacıyla yapılan kısa süreli seyahatler için başvurulan C Tipi Schengen vizesidir. Başvurunun niteliğine göre davetiye ve ziyaret edilen kişiye ilişkin ek belgeler talep edilebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Transit Vize (C Tipi)', 'Schengen Bölgesi üzerinden başka bir ülkeye seyahat ederken transit geçiş için vizeye ihtiyaç duyan yolcuların başvurduğu vize türüdür. Transit vize gerekliliği, seyahat güzergâhına ve yolcunun vatandaşlığına göre değişebilir.', 3),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Fuar, Kongre ve Etkinlik Vizesi (C Tipi)', 'Fuar, kongre, konferans, kültürel, bilimsel veya sportif etkinliklere katılmak amacıyla yapılan kısa süreli seyahatler için başvurulan C Tipi Schengen vizesidir.', 4),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Öğrenci Vizesi (D Tipi Ulusal Vize)', '90 günü aşan eğitim programlarına katılmak veya uzun süreli eğitim amacıyla ilgili ülkede bulunmak isteyen kişilerin başvurması gereken ulusal D Tipi vizedir.', 5),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Çalışma Vizesi (D Tipi Ulusal Vize)', 'İlgili ülkede uzun süreli çalışmak isteyen kişilerin başvurması gereken ulusal D Tipi vizedir. Başvuru koşulları ve gerekli belgeler ülkeye göre değişiklik gösterir.', 6),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Aile Birleşimi Vizesi (D Tipi Ulusal Vize)', 'İlgili ülkede yasal olarak yaşayan aile bireylerinin yanına uzun süreli yerleşmek isteyen kişilerin başvurduğu ulusal D Tipi vizedir. Başvuru şartları ülkenin ulusal mevzuatına göre belirlenir.', 7);
INSERT INTO country_process_steps (country_id, title, description, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Vize Türünü Belirleyin', 'Schengen vize başvurusu, seyahat amacının ve vize türünün belirlenmesiyle başlar.', 0),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Başvuru Ülkesini Seçin', 'Doğru başvuru ülkesinin seçilmesi gerekir; başvuru, seyahatinizin ana destinasyonu olan ülkenin yetkili makamlarına yapılır.', 1),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Belgeleri Hazırlayın', 'Gerekli belgeler hazırlanır. Başvuru şartları ve prosedürler, başvuracağınız ülkeye göre değişebilir.', 2),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Randevu ve Biyometri İşlemlerini Tamamlayın', 'Randevu ve biyometri işlemlerinin tamamlanması gerekir.', 3),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Başvurunuzu Teslim Edin', 'Hazırlanan başvuru dosyası yetkili başvuru kanalı aracılığıyla teslim edilir.', 4),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Sonucu Bekleyin', 'Başvurunun değerlendirilmesi aşaması ile süreç tamamlanır.', 5);
INSERT INTO country_faqs (country_id, question, answer, sort_order) VALUES
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vize başvurusunu ne kadar önce yapmalıyım?', 'Schengen vize başvurunuzu, planlanan seyahat tarihinizden en erken 6 ay önce ve kural olarak en geç 15 takvim günü önce yapabilirsiniz. Ancak 15 günlük süre başvuruyu son dakikaya bırakmak için güvenli bir zaman aralığı değildir. Randevu bulunabilirliği, resmî tatiller ve başvurunun değerlendirme süresinin uzayabilmesi nedeniyle başvurunuzu daha erken yapmanız önerilir. Normal değerlendirme süresi 15 gün olmakla birlikte, gerekli durumlarda 45 güne kadar uzayabilir.', 0),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vizesi kaç günde sonuçlanır?', 'Schengen vize başvuruları, normal şartlarda başvurunun yetkili makama ulaştığı tarihten itibaren 15 takvim günü içinde sonuçlandırılır. Başvurunun daha ayrıntılı incelenmesi veya ek belge talep edilmesi halinde bu süre 45 güne kadar uzayabilir.', 1),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vize ücreti ne kadar?', 'Schengen vize harcı ve başvuru sırasında ödenebilecek hizmet bedelleri zaman içinde değişebilir. Güncel ücretler, başvuru yapılacak ülkeye ve yetkili başvuru merkezine göre kontrol edilmelidir.', 2),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vizesi için banka hesabımda ne kadar para bulunmalıdır?', 'Schengen vizesi için tüm ülkeler açısından geçerli tek bir minimum banka bakiyesi bulunmaz. Gerekli finansal yeterlilik, başvurulan ülkenin belirlediği günlük geçim tutarı, seyahat süresi ve konaklama gibi unsurlara göre değerlendirilir. Hesabınızdaki bakiyenin seyahat masraflarınızı karşılayabilecek düzeyde olması ve gelir durumunuzla uyumlu olması gerekir.', 3),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vizesi için pasaportumun en az kaç ay geçerliliği olmalıdır?', 'Pasaportunuzun, Schengen Bölgesi''nden planlanan çıkış tarihinizden sonra en az 3 ay daha geçerli olması gerekir. Ayrıca pasaportunuzun son 10 yıl içinde düzenlenmiş ve en az 2 boş sayfasının bulunması gerekir.', 4),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vizesi için parmak izi vermem gerekir mi?', 'Schengen vize başvurularında parmak izi alınması ve biyometrik veri kaydedilmesi genel olarak zorunludur. Ancak daha önce Schengen vizesi başvurusu sırasında parmak izi verdiyseniz ve bu biyometrik veriler 59 ay içinde yeniden kullanılabiliyorsa tekrar parmak izi vermeniz gerekmeyebilir.', 5),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vizesi ile tüm Schengen ülkelerine seyahat edebilir miyim?', 'Evet. Schengen vizesi, vizenizin geçerlilik alanı, giriş sayısı ve izin verilen kalış süresi dahilinde Schengen Bölgesi''ndeki ülkelere seyahat etmenize olanak tanır.', 6),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'İlk girişimi vizeyi aldığım ülkeden yapmak zorunda mıyım?', 'Hayır. Schengen vizesi aldığınız ülkeden giriş yapmanız genel olarak zorunlu değildir. Ancak seyahat planınızın, vize başvurusu sırasında sunduğunuz bilgilerle uyumlu olması ve başvuru yaptığınız ülkenin seyahatinizin ana destinasyonu olması gerekir.', 7),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Tek girişli ve çok girişli Schengen vizesi arasındaki fark nedir?', 'Tek girişli (Single Entry) Schengen vizesi, Schengen Bölgesi''ne bir kez giriş yapmanıza izin verir. Bölgeden çıktıktan sonra vizenizin geçerlilik süresi devam etse bile aynı vizeyle yeniden giriş yapamazsınız. Çok girişli (Multiple Entry) Schengen vizesi ise vizenin geçerlilik süresi ve izin verilen kalış süresi içinde Schengen Bölgesi''ne birden fazla giriş ve çıkış yapmanıza olanak tanır.', 8),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vize başvuruları en çok hangi nedenlerle reddedilir?', 'Schengen vize başvuruları; seyahat amacının yeterince kanıtlanmaması, sunulan belgelerde eksiklik veya tutarsızlık bulunması, yeterli maddi imkânın gösterilememesi ya da başvuru sahibinin seyahat sonunda ülkesine döneceğine ilişkin yeterli kanaat oluşmaması gibi nedenlerle reddedilebilir. Ret gerekçesi, her başvurunun kendi koşulları değerlendirilerek belirlenir.', 9),
  ((SELECT id FROM countries WHERE slug = 'schengen'), 'Schengen vize başvurum reddedilirse tekrar başvuru yapabilir miyim?', 'Evet. Schengen vize başvurunuzun reddedilmesi, yeniden başvuru yapmanıza engel değildir. Ancak yeni bir başvuru yapmadan önce ret gerekçesini değerlendirmeniz ve önceki başvuruda yetersiz veya eksik görülen hususları gidermeniz önemlidir.', 10);
